/* Spanish translation of the Fortinet NSE 4 - FortiOS 7.6 Administrator practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("fortinet-fortigate", {
  "fg1": ["Se desempaca un appliance FortiGate nuevo y un administrador conecta una laptop al puerto MGMT. ¿A qué dirección debe navegar para el primer inicio de sesión en la GUI?", ["HTTPS a 192.168.1.99", "HTTPS a 192.168.100.99:10443", "HTTPS a 10.0.0.1", "HTTPS a 172.16.1.1"], "Los FortiGate de hardware vienen con 192.168.1.99 en la interfaz de administración (o internal/port1). Las otras direcciones son valores predeterminados comunes en equipos de otros fabricantes, no de FortiGate.", [null, "192.168.100.99:10443 es una dirección de administración común en equipos de otros fabricantes (y de puertos al estilo FortiManager/analyzer), no un valor de fábrica de FortiGate.", "10.0.0.1 es una dirección de gateway genérica, no la que trae un FortiGate de fábrica en su interfaz de administración.", "172.16.1.1 es otro gateway arbitrario de rango privado, no el valor predeterminado de FortiGate, que es 192.168.1.99."]],
  "fg2": ["¿Qué ocurre la primera vez que un administrador inicia sesión en un appliance FortiGate con la configuración de fábrica?", ["Inicia sesión como admin con la contraseña fortinet y luego se le pide registrarlo", "Inicia sesión como root con el número de serie del equipo", "Primero debe registrar el equipo en FortiCloud", "Inicia sesión como admin con contraseña en blanco y debe establecer una"], "La cuenta predeterminada es admin con contraseña vacía, y FortiOS obliga a definir una contraseña nueva en el primer inicio de sesión. No existe una cuenta root, y el registro en FortiCloud es opcional para el inicio de sesión local.", ["La contraseña predeterminada está en blanco, no es 'fortinet', y no se requiere registro solo para iniciar sesión localmente.", "FortiOS no tiene cuenta root y nunca te deja iniciar sesión con el número de serie; la cuenta predeterminada es admin.", "El registro en FortiCloud es opcional para el inicio de sesión local; puedes iniciar sesión y administrar el equipo sin él.", null]],
  "fg3": ["La política de seguridad indica que los administradores solo pueden iniciar sesión en el FortiGate desde la subred de administración 10.10.99.0/24. ¿Qué configuración de administrador lo aplica de forma MÁS directa?", ["Una política de contraseñas de administrador más estricta", "Un perfil de administrador personalizado limitado a la VDOM de administración", "Trusted hosts en cada cuenta de administrador", "Autenticación de dos factores para los administradores"], "Los trusted hosts limitan las direcciones de origen desde las que puede iniciar sesión una cuenta de administrador. Los perfiles controlan qué puede cambiar un administrador, no desde dónde inicia sesión, y MFA o las reglas de contraseña no restringen las redes de origen.", ["Una política de contraseñas fortalece las credenciales, pero no restringe desde qué subred de origen puede conectarse un administrador.", "Un perfil de administrador controla qué puede cambiar el administrador, y el alcance por VDOM limita qué VDOM administra, no la IP de origen desde la que inicia sesión.", null, "MFA agrega un segundo factor, pero sigue permitiendo iniciar sesión desde cualquier red; no limita la subred de origen."]],
  "fg4": ["Un auditor necesita ver los registros y los informes en el FortiGate, pero no debe cambiar ninguna configuración. ¿Qué debe crear el administrador?", ["Una cuenta super_admin restringida con trusted hosts en la subred de auditoría", "Un perfil de administrador con acceso de solo lectura a registros e informes", "Un usuario de firewall local en un grupo de usuarios", "Una nueva VDOM que contenga solo la configuración de registros"], "Los perfiles de administrador definen acceso de lectura o de lectura y escritura por área, así que un perfil de solo lectura para Log & Report es lo adecuado. super_admin puede cambiar todo, y los usuarios de firewall no pueden iniciar sesión en la administración.", ["super_admin tiene acceso completo de lectura y escritura, así que incluso con trusted hosts el auditor podría cambiar configuraciones, lo que incumple el requisito.", null, "Un usuario de firewall local se autentica en políticas para el tráfico; no puede iniciar sesión en la GUI de administración.", "Una VDOM separa dominios de configuración; no crea un inicio de sesión de auditor de solo lectura y es mucho más de lo necesario."]],
  "fg5": ["En un clúster FGCP con HA override deshabilitado (el valor predeterminado), ¿qué criterio se compara PRIMERO al elegir el primario?", ["Device priority", "Cantidad de interfaces monitoreadas conectadas", "HA uptime", "El número de serie, ganando el valor más alto"], "Con override deshabilitado, FGCP compara las interfaces monitoreadas, luego el HA uptime, luego la prioridad y luego el número de serie. La prioridad solo se revisa antes que el uptime cuando override está habilitado.", ["La device priority solo se revisa antes que el uptime cuando HA override está habilitado; con override deshabilitado va después del uptime.", null, "El HA uptime se compara en segundo lugar, después de la cantidad de interfaces monitoreadas conectadas, no primero.", "El número de serie es solo el desempate final, que se revisa al último cuando todo lo demás es igual."]],
  "fg6": ["Un administrador sube la prioridad de HA del FortiGate secundario a 250, pero sigue siendo secundario. Override está deshabilitado y ambos equipos tienen todas las interfaces monitoreadas activas. ¿Por qué?", ["El HA uptime se compara antes que la prioridad mientras override está deshabilitado", "La prioridad solo aplica después de reiniciar el clúster dos veces", "FGCP ignora las prioridades mayores a 200", "El número de serie del secundario es menor que el del primario"], "Con override deshabilitado, el equipo con mayor HA uptime (por encima del margen de uptime) se mantiene como primario sin importar la prioridad. Habilitar override, o restablecer el uptime, hace que la prioridad surta efecto.", [null, "La prioridad es un factor real de elección una vez que override está habilitado; no depende de dos reinicios.", "FGCP no limita ni ignora los valores de prioridad mayores a 200; 250 es una prioridad válida.", "El número de serie es solo el último desempate; aquí el uptime ya decide antes de que se considere el serial."]],
  "fg7": ["Después de un failover de HA, los usuarios se quejan de que se cayeron transferencias de archivos largas y sesiones SSH. ¿Qué debe habilitar el administrador para que las sesiones TCP sobrevivan al próximo failover?", ["HA override en ambos miembros del clúster", "Una segunda interfaz de heartbeat dedicada", "Uninterruptible firmware upgrade", "Session pickup en la configuración de HA"], "Session pickup sincroniza la tabla de sesiones para que el nuevo primario pueda continuar las sesiones TCP existentes; está deshabilitado por defecto. Override y los enlaces de heartbeat adicionales afectan la elección y la resiliencia, no la continuidad de las sesiones.", ["HA override cambia qué equipo pasa a primario; no hace nada para conservar las sesiones TCP existentes durante un failover.", "Un segundo enlace de heartbeat mejora la resiliencia del clúster y ayuda a evitar el split brain, pero no transporta la tabla de sesiones para la continuidad.", "Uninterruptible firmware upgrade mantiene el tráfico durante una actualización; no sincroniza sesiones para un failover no planificado.", null]],
  "fg8": ["Dos miembros de HA aparecen como no sincronizados en la GUI. ¿Qué comando compara los checksums de configuración entre los miembros del clúster?", ["get system performance status", "diagnose sys session list", "diagnose sys ha checksum cluster", "diagnose debug flow trace start 10"], "diagnose sys ha checksum cluster muestra el checksum de cada área de configuración en cada miembro para que encuentres qué difiere. Los demás muestran recursos, sesiones y el flujo de paquetes.", ["get system performance status muestra CPU, memoria y sesiones, no los checksums de configuración por área.", "diagnose sys session list vuelca la tabla de sesiones en vivo, que no tiene nada que ver con la sincronización de configuración entre miembros.", null, "Ese comando traza el flujo de paquetes para resolver problemas de conectividad, no los checksums de configuración de HA."]],
  "fg9": ["¿Qué configuraciones deben coincidir para que dos FortiGate formen un clúster FGCP?", ["Hostname, dirección IP de administración y contraseña de admin", "Prefijo del número de serie y fechas de vencimiento de las licencias", "Modelo, firmware, HA group ID, nombre del grupo y contraseña", "Direcciones IP de interfaz en cada puerto"], "FGCP requiere el mismo modelo de hardware y firmware, y que coincidan el HA group ID, el nombre del grupo y la contraseña. Los hostnames y las IP de administración son únicos por miembro.", ["Los hostnames y las IP de administración son únicos por miembro, y la contraseña de admin no es un requisito de coincidencia del clúster FGCP.", "Un prefijo de serial compartido o fechas de licencia iguales no son requisitos para formar FGCP; los miembros pueden diferir en eso.", null, "Las IP de interfaz no se igualan entre miembros; cada equipo conserva su direccionamiento mientras comparten IP/MAC virtuales."]],
  "fg10": ["¿En qué se diferencia el modo activo-activo de FGCP del modo activo-pasivo?", ["Cada miembro tiene su propio conjunto de direcciones IP de interfaz", "El primario comparte las sesiones de inspección de perfiles de seguridad con los secundarios", "Los secundarios enrutan tráfico sin ninguna conexión con el primario", "La sincronización de sesiones está desactivada por diseño"], "En activo-activo, el primario sigue recibiendo el tráfico, pero distribuye a los secundarios las sesiones que necesitan inspección. En activo-pasivo solo el primario procesa el tráfico. El clúster comparte direcciones IP y MAC virtuales en ambos modos.", ["Ambos modos comparten direcciones IP y MAC virtuales; en activo-activo los miembros no tienen cada uno IP de interfaz separadas.", null, "Los secundarios siempre se coordinan con el primario; nunca enrutan de forma independiente sin conexión con él.", "La sincronización de sesiones no está desactivada en activo-activo; el primario distribuye las sesiones de inspección a los secundarios."]],
  "fg11": ["Un FortiGate de sucursal debe unirse al Security Fabric de la oficina central, donde la oficina central es la raíz. ¿Cuál es el enfoque correcto?", ["Habilitar Fabric en la sucursal, apuntarlo a la raíz y autorizarlo ahí", "Importar el respaldo de configuración de la raíz en la sucursal", "Construir un túnel IPsec y habilitar fabric-sync en él", "Solo registrar ambos equipos en la misma cuenta de FortiCare"], "Un FortiGate downstream habilita la conexión al Security Fabric, usa la IP del upstream (raíz), y la raíz lo autoriza por número de serie. Compartir una cuenta de FortiCare o un túnel no crea el Fabric por sí solo.", [null, "Importar el respaldo de configuración de la raíz sobrescribiría la configuración propia de la sucursal y no crea una autorización del Fabric.", "Una conexión Fabric no se establece habilitando sync en un túnel IPsec; el equipo downstream apunta al upstream y es autorizado.", "Compartir una cuenta de FortiCare registra los equipos, pero no los une por sí solo en un Security Fabric."]],
  "fg12": ["¿Qué debe tener el FortiGate raíz antes de poder configurar el Security Fabric?", ["Un FortiManager que administre cada equipo downstream", "Al menos un FortiSwitch conectado por FortiLink", "Un enlace de heartbeat de HA dedicado hacia cada equipo downstream", "Registro en FortiAnalyzer o en un servicio de registro en la nube"], "La raíz del Fabric necesita FortiAnalyzer o registro en la nube (como FortiGate Cloud) para poder construir los registros y las vistas del Fabric. FortiManager y FortiSwitch son dispositivos opcionales del Fabric.", ["FortiManager centraliza la configuración, pero es un dispositivo opcional del Fabric, no un requisito para la raíz.", "Un FortiSwitch por FortiLink es un miembro opcional del Fabric, no es necesario para configurarlo.", "Los enlaces de heartbeat de HA son para clústeres entre equipos emparejados, no un requisito para los miembros downstream del Fabric.", null]],
  "fg13": ["El equipo de seguridad quiere un correo cada vez que cualquier administrador cambie la configuración del FortiGate. ¿Cuál es la forma más sencilla de hacerlo?", ["Un servidor syslog con un filtro que reenvíe los eventos coincidentes a un buzón compartido", "Un informe de registros de eventos programado una vez al día", "Una suscripción a las alertas de brotes de FortiGuard", "Un automation stitch con un desencadenador de cambio de configuración y una acción de correo"], "Los automation stitches combinan un desencadenador (como un cambio de configuración) con acciones (como un correo). Un informe diario no es inmediato, y el reenvío por syslog necesita herramientas adicionales.", ["Un servidor syslog con un filtro de buzón necesita herramientas externas adicionales y es más complejo que un stitch integrado.", "Un informe programado diario no es inmediato, así que los administradores no recibirían un correo en el momento de cada cambio.", "Las alertas de brotes de FortiGuard son notificaciones de inteligencia de amenazas, no alertas sobre cambios de configuración locales.", null]],
  "fg14": ["¿Qué ofrece la función Security Rating?", ["Una puntuación de reputación de FortiGuard para cada sitio web externo", "Calificaciones de ancho de banda en vivo para cada enlace WAN", "Verificaciones de mejores prácticas en los dispositivos del Fabric con una puntuación y correcciones", "Una puntuación de riesgo por usuario basada en inicios de sesión fallidos"], "Security Rating ejecuta verificaciones contra las mejores prácticas de Fortinet en los dispositivos del Fabric y muestra una puntuación con recomendaciones. No califica sitios web ni enlaces WAN.", ["Las puntuaciones de reputación de sitios web provienen del filtrado web de FortiGuard, no de la función Security Rating.", "Las calificaciones de ancho de banda WAN en vivo se muestran en las vistas de SD-WAN/monitoreo, no en Security Rating.", null, "El riesgo por usuario basado en inicios de sesión fallidos no es lo que produce Security Rating; esta audita las mejores prácticas de los dispositivos."]],
  "fg15": ["Un FortiGate entra en memory conserve mode durante un pico de tráfico. ¿Qué configuración global decide si las sesiones que necesitan antivirus basado en proxy pasan sin inspección o se bloquean?", ["ips fail-open", "av-failopen", "tcp-halfopen-timer", "admin-lockout-threshold"], "La configuración av-failopen en system global controla qué hace la inspección por proxy en conserve mode. IPS fail-open controla el motor IPS, y las demás son temporizadores o configuraciones de bloqueo.", ["ips fail-open gobierna el motor IPS cuando está sobrecargado, no el comportamiento del antivirus basado en proxy durante conserve mode.", null, "tcp-halfopen-timer controla cuánto duran las sesiones TCP semiabiertas; no tiene relación con la inspección en conserve mode.", "admin-lockout-threshold limita los inicios de sesión fallidos de administradores; no tiene nada que ver con el AV por proxy bajo presión de memoria."]],
  "fg16": ["¿Qué comando da un resumen rápido del uso de CPU, uso de memoria, cantidad de sesiones y uptime en un FortiGate?", ["get system performance status", "get system status", "get router info routing-table all", "diagnose sys ha status"], "get system performance status resume CPU, memoria, sesiones y uptime. get system status muestra el firmware, el serial y el modo, no los recursos en vivo.", [null, "get system status muestra el firmware, el número de serie y el modo de operación, no la CPU, la memoria ni las sesiones en vivo.", "Ese comando muestra la tabla de enrutamiento, no el uso de recursos.", "diagnose sys ha status informa el estado del clúster de HA, no el resumen de CPU/memoria/sesiones del equipo."]],
  "fg17": ["Un debug flow de una conexión que falla muestra \"Denied by forward policy check (policy 0)\". ¿Qué le indica esto al administrador?", ["Ninguna política coincidió, así que el implicit deny descartó el tráfico", "La política con ID 0 es una política de usuario que espera autenticación", "La búsqueda de ruta falló antes de revisar cualquier política de firewall", "Un IPS sensor de la primera política bloqueó la sesión"], "La política 0 es el implicit deny al final de la lista de políticas, así que ninguna política configurada coincidió. Una falla de enrutamiento o un bloqueo de IPS muestran un mensaje de debug distinto.", [null, "No existe una política de usuario 0; la política 0 es el implicit deny, y una autenticación pendiente produce otro mensaje en el flow.", "Una falla en la búsqueda de ruta muestra un mensaje de 'no route'; aquí sí se revisó una política y coincidió con el implicit deny.", "Un bloqueo de IPS registra la acción de una firma IPS, no una línea 'Denied by forward policy check (policy 0)'."]],
  "fg18": ["Un administrador ejecuta diagnose debug flow filter addr 10.1.1.5 y diagnose debug flow trace start 20, pero no aparece ninguna salida mientras el host envía tráfico. ¿Qué faltó?", ["diagnose debug reset", "execute ping-options source 10.1.1.5", "diagnose sys session clear", "diagnose debug enable"], "La salida de debug solo se imprime en la consola después de diagnose debug enable. Restablecer el debug borra los filtros, y borrar las sesiones interrumpiría a los usuarios sin mostrar nada.", ["diagnose debug reset borra los filtros; ejecutarlo eliminaría el filtro que acabas de definir, no produciría salida.", "Definir una dirección de origen para ping afecta los pings generados localmente, no si el debug flow imprime el tráfico de tránsito.", "Borrar las sesiones interrumpiría a los usuarios y por sí solo tampoco imprimiría salida de debug.", null]],
  "fg19": ["Una política registra solo eventos de seguridad, pero el analista necesita un registro de cada sesión aceptada por ella. ¿Qué se debe cambiar?", ["Habilitar log violation traffic en la política 0", "Subir la severidad del registro de eventos a debug", "Configurar Log allowed traffic en All sessions", "Habilitar el registro en disco local para los registros de eventos"], "All sessions registra cada sesión aceptada; Security events solo registra las sesiones sobre las que actuó un perfil de seguridad. El registro del implicit deny guarda el tráfico denegado, no las sesiones permitidas.", ["La política 0 es el implicit deny; su registro guarda tráfico denegado, no sesiones aceptadas por una política real.", "La severidad del registro de eventos controla el detalle de los registros de sistema/eventos, no el registro por política del tráfico permitido.", null, "Habilitar el registro en disco cambia dónde se almacenan los registros, no si la política registra cada sesión permitida."]],
  "fg20": ["Un FortiGate pequeño sin disco registra en memoria. Tras un reinicio por una actualización de firmware, los registros de ayer desaparecieron. ¿Qué debe hacer el administrador?", ["Aumentar el tamaño del registro en memoria al máximo que permita el modelo", "Enviar los registros a FortiAnalyzer, FortiGate Cloud o syslog", "Bajar la severidad de registro de information a warning", "Habilitar la compresión de registros en el búfer de memoria"], "Los registros en memoria son pequeños y se pierden al reiniciar, así que conservar el historial requiere un destino de registro remoto. Un búfer de memoria más grande o comprimido igual se borra al reiniciar.", ["Un búfer de memoria más grande sigue estando en RAM y se borra al reiniciar, así que los registros de ayer igual se perderían.", null, "Bajar la severidad solo reduce cuánto se registra; no hace que los registros en memoria sobrevivan a un reinicio.", "La compresión ahorra espacio en el mismo búfer volátil; los registros igual se borran cuando el equipo se reinicia."]],
  "fg21": ["¿Qué es un virtual domain (VDOM) en un FortiGate?", ["Una zona DNS que el FortiGate aloja y responde para los clientes internos", "Una instancia separada con sus propias políticas, rutas y configuraciones", "Un grupo de administradores que comparten un perfil de administrador", "Una VLAN que transporta el tráfico de heartbeat de HA"], "Cada VDOM actúa como un FortiGate independiente con sus propias interfaces, enrutamiento y políticas. Las zonas DNS, los grupos de administradores y las VLAN son funciones no relacionadas.", ["Una zona DNS es un elemento de resolución de nombres; una VDOM es una instancia de firewall virtual completa, no una zona alojada.", null, "Una VDOM no es un grupo de administradores; los permisos de administrador se definen con perfiles de administrador.", "Una VDOM no es una VLAN, y el tráfico de heartbeat de HA usa interfaces de heartbeat dedicadas, no una VDOM."]],
  "fg22": ["Un FortiGate ejecuta una versión antigua de 7.0 y debe pasar a FortiOS 7.6. ¿Qué debe hacer PRIMERO el administrador?", ["Respaldar la configuración y seguir la ruta de actualización publicada", "Instalar la imagen 7.6 directamente y reiniciar dos veces", "Restablecer de fábrica y luego restaurar el archivo de configuración de 7.0 en 7.6", "Actualizar solo el miembro secundario de HA y esperar"], "Fortinet publica una ruta de actualización que pasa por versiones intermedias para que la configuración se convierta correctamente, y un respaldo permite revertir. Saltarse pasos puede hacer perder configuraciones.", [null, "Instalar 7.6 directamente y reiniciar puede saltarse versiones intermedias necesarias, con riesgo de una conversión de configuración defectuosa.", "Restaurar un archivo de configuración de 7.0 en 7.6 evita la conversión guiada de la actualización y puede perder o corromper configuraciones.", "Actualizar solo el miembro secundario de HA deja un clúster con firmware mixto y no completa la ruta de migración."]],
  "fg23": ["¿Cómo elige un FortiGate qué política de firewall aplica a una sesión nueva?", ["Usa la política coincidente más específica en cualquier parte de la lista", "Usa la política con el policy ID más bajo", "Combina todas las políticas que coinciden con la sesión", "Revisa las políticas de arriba hacia abajo y usa la primera coincidencia"], "Las políticas se evalúan en el orden de la lista y gana la primera coincidencia. El policy ID es solo una etiqueta; el orden en la lista es lo que decide.", ["FortiGate no elige la política 'más específica' en cualquier parte de la lista; decide el orden de la lista.", "El policy ID más bajo no es el criterio; el ID es solo una etiqueta y no define el orden de evaluación.", "Las políticas no se combinan; exactamente una política (la primera coincidencia) aplica a la sesión.", null]],
  "fg24": ["Un administrador agrega una política que permite a RR. HH. llegar a un servidor de nómina, pero RR. HH. sigue sin poder conectarse. Encima hay una política de denegar más amplia para toda la LAN. ¿Cuál es la solución?", ["Darle a la política de RR. HH. un número de policy ID más bajo", "Habilitar NAT en la política de RR. HH.", "Mover la política de RR. HH. por encima de la política de denegar más amplia", "Agregar el servidor de nómina al destino de la política de denegar"], "Como gana la primera política coincidente, el permiso específico debe estar por encima de la denegación amplia. Cambiar el ID no cambia el orden, y NAT no afecta la coincidencia.", ["Cambiar el policy ID no cambia el orden de la lista, así que la denegación amplia de arriba seguiría coincidiendo primero.", "Habilitar NAT afecta la traducción de direcciones, no qué política coincide, así que RR. HH. seguiría siendo denegado.", null, "Agregar el servidor de nómina al destino de la política de denegar lo bloquearía aún más, lo contrario del objetivo."]],
  "fg25": ["Las conexiones denegadas no aparecen en el registro de tráfico forward. ¿Qué debe habilitar el administrador?", ["Log allowed traffic en All sessions en cada política de aceptar", "Un nivel de severidad más alto en el registro de eventos", "El registro de violation traffic en la política implicit deny", "Captura de paquetes en la interfaz WAN"], "La política implicit deny no registra por defecto. Activar su registro guarda las sesiones que bloquea; el registro del tráfico permitido cubre solo las sesiones aceptadas.", ["El registro del tráfico permitido guarda sesiones aceptadas; no captura las conexiones que bloquea el implicit deny.", "La severidad del registro de eventos gobierna los eventos del sistema, no el registro del tráfico forward denegado.", null, "Una captura de paquetes en la WAN es un diagnóstico manual, no una forma de registrar las conexiones denegadas en el registro de tráfico forward."]],
  "fg26": ["¿Cuál de estos elementos no se usa al hacer coincidir el tráfico con una política de firewall?", ["Las interfaces de entrada y de salida", "Los perfiles de seguridad vinculados a ella", "Las direcciones de origen y de destino", "El servicio y el horario (schedule)"], "FortiGate hace coincidir por interfaces, origen (dirección o usuario), destino, servicio y horario. Los perfiles de seguridad se aplican después de la coincidencia; no la deciden.", ["Las interfaces forman parte de la coincidencia de políticas, así que sí se usan.", null, "Las direcciones de origen y destino son criterios de coincidencia centrales, así que sí se usan.", "El servicio y el horario también son criterios de coincidencia, así que sí se usan."]],
  "fg27": ["Los usuarios internos necesitan acceso a internet, y el FortiGate tiene una sola IP pública en su puerto WAN. ¿Qué opción de NAT de origen es la más sencilla?", ["Habilitar NAT con la dirección de la interfaz de salida", "Crear una VIP para cada host interno", "Habilitar central SNAT con un IP pool one-to-one de direcciones públicas", "Crear una VIP de port forwarding en la IP de la WAN"], "Usar la dirección de la interfaz de salida oculta todos los hosts internos detrás de la IP de la WAN con traducción de puertos. Las VIP son para NAT de destino, y los pools one-to-one necesitan una IP pública por host.", [null, "Una VIP por host es NAT de destino para servicios entrantes, no una forma de dar acceso a internet a los usuarios salientes.", "Central SNAT con un pool one-to-one necesita una IP pública por host y es mucho más complejo de lo necesario para una sola IP WAN.", "Una VIP de port forwarding publica servicios entrantes; no proporciona NAT de origen saliente para los usuarios internos."]],
  "fg28": ["Una empresa tiene cuatro IP públicas y quiere que 800 usuarios internos las compartan para el tráfico saliente. ¿Qué tipo de IP pool es el adecuado?", ["One-to-one", "Fixed port range", "Port block allocation por VIP", "Overload"], "Overload traduce muchas direcciones internas a las direcciones del pool con traducción de puertos. One-to-one le da a cada usuario una IP pública completa, así que solo cuatro usuarios podrían estar conectados.", ["One-to-one le da a cada usuario una IP pública completa, así que con cuatro IP solo cuatro usuarios podrían estar conectados a la vez.", "Fixed port range asigna bloques predecibles de puertos externos, pero no es lo más sencillo para compartir masivamente la salida en este caso.", "Port block allocation está ligado a configuraciones tipo VIP/CGN y no es la opción estándar de overload de muchos a pocos para la salida.", null]],
  "fg29": ["¿Cuál es una limitación de un IP pool one-to-one?", ["Solo se puede usar con túneles IPsec", "Cambia aleatoriamente los puertos de origen en cada paquete que traduce", "Necesita que central SNAT esté habilitado", "Solo pueden conectarse a la vez tantos hosts como direcciones tenga el pool"], "One-to-one asigna a cada host interno su propia dirección externa sin traducción de puertos, así que el tamaño del pool limita los usuarios concurrentes. Funciona con políticas normales.", ["Los pools one-to-one funcionan con políticas IPv4 normales, no solo con túneles IPsec.", "One-to-one no traduce puertos en absoluto, mucho menos los aleatoriza en cada paquete.", "One-to-one se configura directamente en una política; no requiere que central SNAT esté habilitado.", null]],
  "fg30": ["Un servidor web en 10.0.1.10 debe ser accesible desde internet en la IP pública 203.0.113.20. ¿Qué debe configurar el administrador?", ["Un IP pool overload en la política WAN a LAN", "Una ruta estática a 10.0.1.10 a través de la interfaz WAN", "Una VIP que asigne 203.0.113.20 a 10.0.1.10, usada en una política WAN a LAN", "Central SNAT con 10.0.1.10 como origen traducido"], "El NAT de destino se hace con un objeto VIP, que se referencia como destino de una política entrante. Los IP pools y SNAT cambian el origen, no el destino.", ["Un IP pool overload cambia el origen del tráfico saliente; no publica un servidor interno hacia afuera.", "Una ruta estática afecta la selección de rutas, no el NAT de destino; el servidor seguiría sin ser accesible en la IP pública.", null, "Central SNAT traduce la dirección de origen; llegar a un servidor interno desde afuera requiere NAT de destino mediante una VIP."]],
  "fg31": ["Los usuarios externos deben llegar a una aplicación interna en el puerto público 8443, pero el servidor escucha en 443. ¿Cómo se debe configurar la VIP?", ["Crear dos VIP, una por cada puerto, con la misma IP", "Habilitar port forwarding y asignar el 8443 externo al 443 mapeado", "Configurar el servicio de la política en 443 y dejar la VIP estática", "Agregar un servicio personalizado que reescriba 8443 a 443"], "El port forwarding en una VIP traduce tanto la dirección como el puerto. Los servicios solo hacen coincidir el tráfico y nunca reescriben puertos.", ["Dos VIP en la misma IP para un solo servicio es innecesario; una sola VIP con port forwarding maneja el mapeo de 8443 a 443.", null, "Configurar el servicio de la política en 443 no traduce el 8443 externo al 443 interno; los servicios nunca reescriben puertos.", "Un servicio personalizado solo hace coincidir el tráfico en ciertos puertos; no puede reescribir 8443 a 443, que es una función de la VIP."]],
  "fg32": ["¿Qué cambia cuando se habilita central SNAT en un FortiGate?", ["El SNAT sale de las políticas y pasa a una tabla SNAT separada que se evalúa de arriba hacia abajo", "Cada política usa automáticamente la IP de la WAN como origen", "Las VIP dejan de funcionar hasta que se vuelvan a crear", "El NAT de destino también se mueve a las políticas de firewall individuales"], "Con central SNAT, las reglas de NAT de origen se definen en su propia tabla ordenada en lugar de por política. El NAT de destino sigue usando las VIP (tabla DNAT y VIP).", [null, "Central SNAT no obliga a cada política a usar la IP de la WAN; tú defines reglas SNAT explícitas en la tabla.", "Las VIP siguen funcionando con central SNAT; el NAT de destino sigue usando la tabla de VIP y no hay que recrearlas.", "El NAT de destino no se mueve a las políticas; se queda en la tabla VIP/DNAT y solo el SNAT pasa a ser central."]],
  "fg33": ["Los usuarios necesitan acceso a Microsoft 365, y el administrador no quiere mantener su lista larga y cambiante de IP. ¿Qué debe usar la política como destino?", ["Una entrada de Internet Service Database (ISDB) para Microsoft 365", "Un objeto de dirección FQDN para www.microsoft.com y login.microsoftonline.com", "Un objeto de dirección de geografía para Estados Unidos", "Un FQDN comodín para *.com"], "FortiGuard mantiene actualizados los objetos ISDB con las direcciones y puertos del servicio. Un solo FQDN omite muchos endpoints, y los objetos de geografía o comodín son demasiado amplios.", [null, "Un par de objetos FQDN omite los muchos endpoints cambiantes que usa Microsoft 365, así que el acceso quedaría incompleto.", "Un objeto de geografía de EE. UU. es demasiado amplio y permitiría todos los sitios alojados en EE. UU., no solo Microsoft 365.", "Un comodín *.com es prácticamente todo internet y no ofrece ninguna restricción significativa."]],
  "fg34": ["Los sitios de juegos solo deben permitirse de 12:00 a 13:00 los días hábiles. ¿Qué se debe vincular a la política de permitir?", ["Un schedule de una sola vez para hoy a las 12:00", "Una acción de advertencia de web filter en la categoría de juegos", "Un traffic shaper limitado al mediodía", "Un schedule recurrente para días hábiles de 12:00 a 13:00"], "Los schedules recurrentes se repiten en los días y horas elegidos. Los schedules de una sola vez se ejecutan una vez, y los shapers limitan el ancho de banda, no el horario.", ["Un schedule de una sola vez se ejecuta solo hoy; no repetirá la ventana del mediodía cada día hábil.", "Una acción de advertencia de web filter muestra una página para continuar; no restringe el acceso a una franja horaria.", "Un traffic shaper limita el ancho de banda, no las horas en que se permiten los sitios.", null]],
  "fg35": ["Una política exige que los usuarios estén en el grupo Staff, pero los usuarios nunca ven una página de inicio de sesión y la navegación falla. El DNS hacia internet solo lo permite esa misma política. ¿Cuál es la solución?", ["Cambiar el puerto del captive portal a TCP 53", "Deshabilitar la política implicit deny para que el tráfico sin coincidencia pueda llegar al portal", "Permitir DNS en una política por encima de ella sin requisito de usuario", "Configurar la acción de la política en Monitor"], "Antes de que pueda aparecer la página de inicio de sesión, el navegador debe resolver nombres, y el DNS no puede desencadenar la solicitud de inicio de sesión. Una política DNS separada sin usuarios lo resuelve; deshabilitar el implicit deny sería inseguro.", ["El captive portal no funciona en TCP 53; cambiar el puerto del portal a 53 no resuelve los nombres antes del inicio de sesión.", "Deshabilitar el implicit deny es inseguro e innecesario; el problema real es que el DNS depende de la política con autenticación.", null, "Configurar la política en Monitor cambia el registro/acción, pero sigue sin permitir que el DNS resuelva antes de que aparezca la página de inicio de sesión."]],
  "fg36": ["¿Cuál es la diferencia entre la autenticación de firewall activa y la pasiva?", ["La activa usa RADIUS; la pasiva usa solo usuarios locales", "La activa le pide datos al usuario; la pasiva lo identifica a partir de otras fuentes", "La activa funciona solo para administradores; la pasiva solo para invitados", "La activa necesita FSSO; la pasiva necesita un captive portal"], "La autenticación activa le pide credenciales al usuario (captive portal). Los métodos pasivos como FSSO saben quién inició sesión a partir de los eventos de inicio de sesión de Windows, sin solicitud.", ["La autenticación activa no está ligada a RADIUS, y la pasiva no se limita a usuarios locales; la diferencia es pedir datos o no.", null, "La activa no es solo para administradores ni la pasiva solo para invitados; ambas aplican a los usuarios de firewall en general.", "La activa usa un captive portal (no FSSO), y los métodos pasivos como FSSO no requieren un captive portal."]],
  "fg37": ["El FortiGate debe consultar la pertenencia a grupos de los usuarios en Active Directory por LDAP. ¿Qué tipo de bind debe usar la entrada del servidor LDAP?", ["Anonymous, para no almacenar credenciales", "Regular, con el DN y la contraseña de una cuenta de servicio", "Simple, con la propia cuenta del administrador", "Kerberos, sin ninguna cuenta de bind configurada"], "El bind Regular permite al FortiGate iniciar sesión con una cuenta de servicio para buscar en el directorio. Active Directory normalmente rechaza las búsquedas anónimas, y el bind Simple no puede buscar pertenencias a grupos.", ["Active Directory normalmente rechaza las búsquedas anónimas, así que un bind anónimo no puede consultar la pertenencia a grupos.", null, "El bind Simple con la propia cuenta del administrador no es la forma en que FortiGate busca en AD; se usa un bind Regular con cuenta de servicio.", "LDAP en FortiGate no usa un bind Kerberos sin cuenta; necesita una cuenta de bind Regular para buscar."]],
  "fg38": ["Solo los miembros del grupo de AD Sales deben poder usar una política. El servidor LDAP ya está definido. ¿Qué debe hacer después el administrador?", ["Crear un grupo de usuarios de firewall que haga referencia al servidor LDAP y al DN de Sales", "Crear un usuario local llamado Sales con LDAP como contraseña", "Agregar el servidor LDAP directamente al origen de la política", "Crear un perfil de administrador llamado Sales"], "Un grupo de usuarios de firewall con un servidor remoto y una coincidencia de grupo permite que las políticas exijan ese grupo de AD. Las políticas usan grupos de usuarios, no entradas de servidores LDAP, y los perfiles de administrador son para administradores.", [null, "Un usuario local con LDAP como contraseña no es la forma de referenciar grupos remotos de AD; se usa un grupo de usuarios.", "Las políticas referencian grupos de usuarios, no entradas de servidores LDAP, así que agregar el servidor al origen no funcionará.", "Un perfil de administrador gobierna a los administradores de la GUI, no a los usuarios de firewall que se autentican en una política."]],
  "fg39": ["En el modo DC agent de FSSO, ¿qué hace el DC agent?", ["Pide credenciales a los usuarios en su navegador", "Envía los inicios de sesión de los usuarios directamente a FortiAnalyzer", "Consulta de forma remota el registro de cada estación de trabajo para obtener el nombre del usuario conectado", "Captura los eventos de inicio de sesión del DC y los envía al collector agent"], "El DC agent se ejecuta en cada controlador de dominio y reenvía los eventos de inicio de sesión al collector agent, que actualiza el FortiGate. Las solicitudes en el navegador son autenticación activa.", ["Las solicitudes de credenciales en el navegador son autenticación activa (captive portal), no lo que hace el DC agent de FSSO.", "El DC agent envía los eventos de inicio de sesión al collector agent, no directamente a FortiAnalyzer.", "Consultar de forma remota el registro de cada estación de trabajo describe otro método (sin agente en las estaciones), no el modo DC agent.", null]],
  "fg40": ["El equipo de Windows no permite ningún software en los controladores de dominio, pero el FortiGate aún debe identificar a los usuarios con FSSO. ¿Qué se debe usar?", ["Modo DC agent con el agente en cada servidor miembro", "RADIUS single sign-on desde los controladores de dominio", "Modo polling, leyendo de forma remota los registros de eventos de seguridad del DC", "Autenticación por captive portal con LDAP"], "El modo polling (desde el collector agent o sin agente en el FortiGate) lee los eventos de inicio de sesión sin software en los DC. Un captive portal es autenticación activa, no single sign-on.", ["El modo DC agent requiere software en los controladores de dominio, lo que el equipo de Windows prohibió.", "RADIUS single sign-on es otro mecanismo y no es la opción de polling de FSSO que lee los registros de eventos del DC.", null, "Un captive portal es autenticación activa que pide datos a los usuarios; no es single sign-on de FSSO."]],
  "fg41": ["Los usuarios de FSSO de la mayoría de los grupos de AD coinciden con las políticas, pero los miembros del nuevo grupo Finance nunca coinciden. ¿Cuál es la causa MÁS probable?", ["Los usuarios de Finance inician sesión con más frecuencia que los demás", "La política implicit deny está configurada para registrar todas las sesiones", "Finance no está entre los grupos monitoreados por la configuración de FSSO", "El nombre del grupo Finance tiene mayúsculas que FSSO ignora"], "FSSO solo envía los grupos seleccionados (group filter) en el collector o en el FortiGate, así que un grupo nuevo debe agregarse. La configuración de registros y las mayúsculas no impiden la coincidencia.", ["La frecuencia con que los usuarios inician sesión no afecta la coincidencia de FSSO; el grupo simplemente debe estar en el conjunto monitoreado.", "El registro del implicit deny guarda el tráfico descartado; no impide que grupos específicos de FSSO coincidan con las políticas.", null, "FSSO no descarta grupos silenciosamente por tener mayúsculas; el grupo debe agregarse al filtro."]],
  "fg42": ["La empresa quiere autenticación de dos factores para los usuarios de firewall con los tokens propios de Fortinet. ¿Qué debe configurar el administrador?", ["Habilitar dos factores solo en el perfil de administrador", "Asignar un FortiToken a cada cuenta de usuario", "Agregar un segundo servidor LDAP como respaldo", "Exigir contraseñas más largas a los usuarios locales"], "FortiToken (de hardware o móvil) se asigna por usuario para agregar un código de un solo uso. La configuración del perfil de administrador afecta a los administradores, y un servidor LDAP de respaldo es redundancia, no un segundo factor.", ["Los dos factores en el perfil de administrador protegen a los administradores, no a los usuarios de firewall que necesitan MFA aquí.", null, "Un servidor LDAP de respaldo agrega redundancia a la autenticación, no un segundo factor de autenticación.", "Las contraseñas más largas fortalecen un solo factor, pero no proporcionan el token de dos factores que pide el requisito."]],
  "fg43": ["¿Qué revisa la inspección de certificados (certificate inspection) en una sesión HTTPS?", ["Los detalles del handshake TLS, como el SNI y los nombres del certificado", "La solicitud y la respuesta HTTP completas descifradas", "Solo el número de puerto de destino", "Los archivos descargados dentro de la sesión, comparados con firmas de antivirus"], "La inspección de certificados lee el handshake no cifrado (SNI y certificado) sin descifrar el contenido, así que no puede analizar archivos. La inspección profunda (deep inspection) descifra el contenido.", [null, "Leer la solicitud y la respuesta completas descifradas requiere deep inspection, no certificate inspection.", "La inspección de certificados lee los detalles del handshake, no solo el número de puerto de destino.", "Analizar los archivos descargados contra firmas de AV requiere descifrar el contenido, lo que certificate inspection no hace."]],
  "fg44": ["El antivirus detecta malware de prueba por HTTP, pero no por HTTPS. La política usa certificate inspection. ¿Qué se debe cambiar?", ["Cambiar el perfil de antivirus a quick scan", "Habilitar certificate inspection también en el puerto WAN", "Aumentar el tamaño máximo de archivo del antivirus", "Usar deep inspection para que se descifre el contenido"], "Sin descifrado, el FortiGate no puede ver los archivos dentro de TLS. Deep inspection descifra y vuelve a cifrar para que el AV pueda analizarlos.", ["Un AV en modo quick scan no permite al FortiGate ver dentro de TLS cifrado; el tráfico sigue sin descifrarse.", "Habilitar certificate inspection en el puerto WAN sigue sin descifrar el contenido, así que los archivos dentro de HTTPS siguen ocultos.", "Aumentar el tamaño máximo de archivo del AV no ayuda cuando el archivo no se puede ver sin descifrar.", null]],
  "fg45": ["Tras habilitar deep inspection, todos los usuarios ven advertencias de certificado en el navegador. ¿Cuál es la solución adecuada?", ["Volver a configurar el perfil solo con certificate inspection", "Importar el certificado de cada sitio web en el FortiGate", "Deshabilitar TLS 1.3 en el FortiGate", "Hacer que todos los dispositivos cliente confíen en la CA de firma del FortiGate"], "El FortiGate vuelve a firmar los certificados de los servidores con su CA, así que los clientes deben confiar en esa CA (distribuida por GPO o MDM). Volver atrás elimina el descifrado, y no se trabaja importando certificados de sitios.", ["Volver a certificate inspection elimina por completo el descifrado y pierdes la deep inspection que querías mantener.", "No se importa el certificado de cada sitio web; el FortiGate vuelve a firmar con su propia CA, en la que los clientes deben confiar.", "Deshabilitar TLS 1.3 no elimina las advertencias, que se deben a que los clientes no confían en la CA de firma del FortiGate.", null]],
  "fg46": ["El área legal exige que el tráfico de banca en línea nunca se descifre. ¿Cómo puede mantenerse deep inspection para todo lo demás?", ["Poner los sitios bancarios en un filtro de URL estático con Block", "Usar una política separada sin perfiles de seguridad para todos", "Exentar la categoría Finance and Banking en el perfil SSL", "Deshabilitar la inspección SSL los viernes con un schedule"], "Los perfiles de inspección SSL pueden exentar del descifrado categorías de FortiGuard o direcciones. Bloquear la banca es incorrecto, y quitar los perfiles para todos pierde protección.", ["Bloquear los sitios bancarios deniega el tráfico por completo; el objetivo es permitirlo sin descifrarlo nunca.", "Quitar todos los perfiles de seguridad para todos pierde protección de forma amplia; solo hay que exentar la banca del descifrado.", null, "Un schedule los viernes que deshabilita la inspección SSL es arbitrario y seguiría descifrando la banca los demás días."]],
  "fg47": ["Una aplicación de banca móvil falla solo cuando se aplica deep inspection, aunque los navegadores funcionan bien. ¿Cuál es la causa probable?", ["La aplicación requiere que certificate inspection esté desactivada", "La aplicación fija (pinning) su certificado y rechaza el que se volvió a firmar", "El FortiGate bloquea todos los puertos de destino mayores a 1024", "La aplicación usa IPv6, que deep inspection siempre descarta en FortiOS 7.6"], "El certificate pinning hace que la aplicación acepte solo su certificado esperado, así que rechaza el del FortiGate. Exentar de la inspección los destinos de la aplicación lo resuelve.", ["El problema no es que la aplicación necesite certificate inspection desactivada en general; es el pinning que rechaza el certificado vuelto a firmar.", null, "El FortiGate no está bloqueando puertos altos; los navegadores hacia el mismo servicio funcionan, lo que apunta al pinning y no a un bloqueo de puertos.", "FortiOS 7.6 no descarta universalmente IPv6 con deep inspection; que el navegador funcione lo descarta y apunta al pinning."]],
  "fg48": ["¿Cómo se compara la inspección basada en proxy con la inspección basada en flujo?", ["Proxy almacena el contenido en búfer y ofrece más funciones con mayor costo", "Proxy siempre es más rápido porque omite el búfer", "Proxy solo funciona con IPS, no con antivirus", "Proxy no puede analizar tráfico HTTP"], "El modo proxy almacena archivos completos en búfer y admite funciones adicionales, usando más recursos. El modo flujo inspecciona a medida que pasan los paquetes, con menor latencia.", [null, "El modo proxy almacena archivos completos en búfer, así que en general es más lento que el modo flujo, no siempre más rápido.", "La inspección por proxy admite antivirus (incluido CDR), así que no se limita solo a IPS.", "El modo proxy puede analizar HTTP y otros protocolos; no es incapaz de analizar HTTP."]],
  "fg49": ["En el modo NGFW basado en perfiles de FortiOS 7.6, ¿dónde se elige el modo de inspección (flujo o proxy)?", ["En cada política de firewall", "Una sola vez de forma global para todo el FortiGate", "Solo en cada perfil de antivirus", "En cada interfaz física"], "El modo de inspección se define por política de firewall, así que una política puede usar proxy mientras otra usa flujo. No es una configuración por interfaz ni solo global.", [null, "En el modo basado en perfiles, el modo de inspección es por política, no una sola configuración global para todo el equipo.", "La elección entre flujo y proxy se hace en la política, no solo dentro del perfil de antivirus.", "El modo de inspección no se elige por interfaz física; es una configuración por política."]],
  "fg50": ["¿Qué cambia en el modo NGFW basado en políticas (policy-based)?", ["Las políticas de firewall se reemplazan por rutas estáticas", "Los perfiles de seguridad solo pueden usar inspección por proxy", "La autenticación se elimina del FortiGate", "Las aplicaciones y las categorías de URL van directamente en las políticas de seguridad"], "En el modo basado en políticas, las políticas de seguridad referencian directamente aplicaciones y categorías, mientras que la inspección SSL y la traducción de direcciones se manejan en políticas separadas. El enrutamiento y la autenticación siguen existiendo.", ["Las rutas estáticas no reemplazan a las políticas de firewall en el modo NGFW basado en políticas; el enrutamiento sigue funcionando por separado.", "Los perfiles de seguridad no se restringen a la inspección por proxy en el modo basado en políticas; la inspección por flujo sigue disponible.", "La autenticación no se elimina en el modo basado en políticas; la identificación y la autenticación de usuarios siguen funcionando.", null]],
  "fg51": ["La categoría Social Networking está bloqueada, pero el equipo de marketing debe acceder a una página de la empresa en un sitio bloqueado. El administrador agrega la URL al filtro de URL estático. ¿Qué acción permite el paso?", ["Allow", "Monitor", "Exempt", "Block"], "El filtro de URL estático se revisa antes que las categorías de FortiGuard. Exempt omite las verificaciones posteriores, mientras que Allow continúa hacia la verificación de categoría, que igual lo bloquearía.", ["Allow permite la URL, pero la sigue pasando a la verificación de categoría de FortiGuard, que volvería a bloquear el sitio de redes sociales.", "Monitor solo registra y permite sin omitir las verificaciones posteriores, así que el bloqueo por categoría seguiría aplicando.", null, "Block denegaría la página, lo contrario de permitir que el equipo de marketing acceda a ella."]],
  "fg52": ["Una categoría de FortiGuard está configurada en Warning en el perfil de web filter. ¿Qué ve el usuario?", ["El sitio con un banner que no se puede cerrar", "Una página de advertencia que le permite elegir continuar", "Una página de inicio de sesión que requiere credenciales de un grupo permitido", "Una página de bloqueo sin forma de continuar"], "Warning muestra una página intermedia y permite al usuario continuar. Authenticate pide credenciales, y Block no da opción.", ["Un banner que no se puede cerrar no es el comportamiento de Warning; Warning presenta una página en la que el usuario puede hacer clic para continuar.", null, "Una página de credenciales/inicio de sesión es la acción Authenticate, no Warning.", "Una página de bloqueo sin forma de continuar es la acción Block, mientras que Warning permite al usuario seguir."]],
  "fg53": ["Durante una caída de FortiGuard, el web filter bloquea todos los sitios web. ¿Qué configuración del perfil permitiría que los sitios carguen cuando no se puede obtener una calificación?", ["Block invalid URLs", "Allow websites when a rating error occurs", "Enforce safe search on all search engines", "Rate images by URL"], "Cuando el servidor de calificaciones no está disponible, esta opción permite los sitios en lugar de bloquearlos. Las demás opciones afectan URL no válidas, buscadores e imágenes.", ["Bloquear URL no válidas maneja direcciones mal formadas, no sitios que fallan porque el servidor de calificaciones no está disponible.", null, "Forzar la búsqueda segura restringe los buscadores; no hace nada ante caídas del servidor de calificaciones.", "Calificar imágenes por URL controla la clasificación de imágenes, no lo que ocurre cuando no se puede obtener una calificación."]],
  "fg54": ["¿Cuál es una ventaja de un DNS filter frente a un web filter?", ["Bloquea dominios maliciosos al momento de la consulta para cualquier aplicación, sin descifrado", "Descifra HTTPS sin un certificado de CA", "Analiza los archivos descargados en busca de malware", "Elimina la necesidad de políticas de firewall"], "El filtrado DNS califica el dominio de la consulta, así que funciona con cualquier protocolo y no necesita inspección TLS. No analiza archivos ni reemplaza las políticas.", [null, "El filtrado DNS no descifra HTTPS; inspecciona la consulta DNS y no implica descifrado ni CA.", "El filtrado DNS no analiza los archivos descargados en busca de malware; eso lo hace el antivirus.", "El filtrado DNS complementa las políticas de firewall; no elimina su necesidad."]],
  "fg55": ["La empresa debe detener el intercambio de archivos peer-to-peer, como BitTorrent. ¿Cuál es el control MÁS eficaz?", ["Una política de firewall que bloquee solo el puerto TCP 6881", "Un web filter que bloquee la categoría peer-to-peer file sharing", "Una política DoS con un límite de sesiones bajo", "Un sensor de application control que bloquee la categoría P2P"], "Las aplicaciones P2P cambian de puerto y usan cifrado, así que el application control basado en firmas es la forma confiable. Bloquear un puerto o una categoría web deja pasar la mayor parte del tráfico.", ["Bloquear solo TCP 6881 falla porque las aplicaciones P2P saltan a otros puertos, así que la mayor parte del tráfico de BitTorrent pasa.", "La categoría web peer-to-peer califica sitios web y no detecta el tráfico de las aplicaciones que no depende de esos sitios.", "Un límite de sesiones DoS frena inundaciones, no el tráfico de aplicaciones P2P identificadas.", null]],
  "fg56": ["Facebook debe seguir permitido, pero los juegos de Facebook deben bloquearse. ¿Cómo se debe configurar application control?", ["Bloquear toda la categoría Social.Media", "Agregar facebook.com al filtro de URL estático como Block", "Agregar un override que bloquee solo la firma de los juegos de Facebook", "Bloquear la categoría de juegos en el DNS filter"], "Los application overrides actúan sobre firmas específicas, así que se pueden bloquear los juegos mientras Facebook sigue permitido. Bloquear la categoría o el dominio bloquearía el propio Facebook.", ["Bloquear toda la categoría Social.Media bloquearía el propio Facebook, no solo sus juegos.", "Agregar facebook.com al filtro de URL como Block deniega todo Facebook, no solo los juegos.", null, "El DNS filter no tiene una categoría de juegos que bloquear y no puede distinguir los juegos dentro de Facebook."]],
  "fg57": ["Application control detecta la aplicación de almacenamiento en la nube, pero no puede bloquear las cargas de archivos dentro de ella. Solo está habilitada certificate inspection. ¿Por qué?", ["Application control nunca funciona con tráfico HTTPS", "La aplicación está en la allowlist de FortiGuard", "Las acciones dentro de la aplicación quedan ocultas sin deep inspection", "El control de cargas necesita un DNS filter en modo proxy"], "El SNI revela qué aplicación se usa, pero acciones como la carga están dentro del contenido cifrado. Deep inspection las expone a las firmas.", ["Application control sí funciona con HTTPS mediante el SNI; la limitación es ver las acciones dentro del contenido cifrado.", "La aplicación no está en una allowlist; la verdadera razón por la que las cargas son invisibles es la falta de deep inspection.", null, "El control de cargas no requiere un DNS filter en modo proxy; requiere deep inspection para ver las acciones dentro de la aplicación."]],
  "fg58": ["¿Cómo maneja el antivirus basado en proxy un archivo descargado?", ["Analiza los paquetes a medida que pasan y nunca almacena datos en búfer", "Almacena todo el archivo en búfer, lo analiza y luego lo envía", "Solo compara el nombre del archivo con una lista", "Reenvía el archivo y analiza una copia después"], "El modo proxy retiene el archivo completo hasta que termina el análisis, lo que le permite bloquearlo o reemplazarlo. El modo flujo analiza a medida que pasan los datos y solo retiene el último paquete hasta el veredicto.", ["Analizar los paquetes a medida que pasan sin búfer describe el antivirus basado en flujo, no el basado en proxy.", null, "El AV por proxy inspecciona el contenido del archivo, no solo compara su nombre con una lista.", "El AV por proxy retiene el archivo hasta terminar el análisis; no lo reenvía primero para analizar una copia después."]],
  "fg59": ["A los documentos de Office en el correo se les debe quitar el contenido activo, como las macros, antes de entregarlos. ¿Qué función lo hace?", ["Content disarm and reconstruction en el antivirus basado en proxy", "Antivirus basado en flujo con la base de datos predeterminada", "Un IPS sensor con un filtro de severidad crítica", "Un DNS filter que bloquee dominios recién observados"], "Content disarm and reconstruction elimina el contenido activo y reconstruye el archivo; necesita inspección basada en proxy. IPS y el filtrado DNS no reconstruyen archivos.", [null, "El antivirus basado en flujo busca malware conocido, pero no elimina macros ni reconstruye archivos; eso lo hace CDR.", "Un IPS sensor detecta patrones de exploits; no quita contenido activo de documentos de Office.", "Un DNS filter bloquea dominios al momento de la consulta; no puede desarmar macros dentro de adjuntos de correo."]],
  "fg60": ["¿Qué agrega al análisis antivirus el envío de archivos a FortiSandbox (o FortiGate Cloud Sandbox)?", ["Una base de datos de firmas más rápida para virus conocidos", "Descifrado de tráfico HTTPS sin un certificado de CA", "Bloqueo de spam por reputación del remitente", "Análisis de comportamiento de archivos desconocidos en un sandbox"], "El sandboxing ejecuta archivos desconocidos para ver qué hacen y detecta malware nuevo que las firmas no encuentran. No descifra tráfico ni filtra spam.", ["El sandboxing no es simplemente una base de datos de firmas más rápida; ejecuta archivos desconocidos para observar su comportamiento.", "El sandboxing no descifra HTTPS; el descifrado lo hace la SSL deep inspection, no el sandbox.", "El filtrado de spam por reputación del remitente es antispam, no lo que ofrece un sandbox.", null]],
  "fg61": ["Un administrador quiere proteger los servidores Windows de la DMZ contra exploits conocidos sin habilitar todas las firmas de IPS. ¿Qué debe hacer?", ["Habilitar todas las firmas con la acción pass", "Aplicar antivirus en modo proxy a la DMZ", "Crear una política DoS para la subred de la DMZ", "Filtrar el IPS sensor por destino servidor y sistema operativo Windows"], "Los filtros del IPS sensor seleccionan firmas por destino, sistema operativo, severidad y protocolo, manteniendo la inspección relevante. Las políticas de antivirus y DoS no detienen intentos de exploit.", ["Habilitar todas las firmas con la acción pass no inspeccionaría nada de forma útil y no bloquea ningún exploit.", "El antivirus en modo proxy analiza malware en archivos, no intentos de explotar vulnerabilidades de servidores.", "Una política DoS limita inundaciones y anomalías, no firmas de exploits conocidos dirigidos a los servidores.", null]],
  "fg62": ["Un servidor web público recibe una inundación SYN. ¿Qué función de FortiGate está diseñada para limitarla antes de la búsqueda de políticas de firewall?", ["Un application control override para el servidor web", "Una cuota de web filter", "Una política DoS con un umbral tcp_syn_flood", "Un IP pool con overload"], "Las políticas DoS se revisan temprano y aplican umbrales de anomalías como las inundaciones SYN. Application control, el filtrado web y los IP pools no manejan inundaciones.", ["Un application control override identifica aplicaciones; no es el control temprano de anomalías que limita las inundaciones SYN.", "Una cuota de web filter limita el tiempo o volumen de navegación, no las tasas de inundación TCP SYN.", null, "Un IP pool overload es NAT de origen; no hace nada para limitar una inundación SYN."]],
  "fg63": ["¿Qué hace IPS fail-open cuando está habilitado?", ["Bloquea todo el tráfico hasta que se recupera el motor IPS", "Deja pasar el tráfico sin inspeccionar si el motor IPS está sobrecargado", "Envía el tráfico a FortiSandbox cuando falla IPS", "Detiene el registro para ahorrar memoria"], "Fail-open prioriza la disponibilidad dejando pasar el tráfico cuando el motor IPS no da abasto. Si está deshabilitado, el tráfico se descarta.", ["Fail-open hace lo contrario de bloquear todo el tráfico; deja pasar el tráfico cuando IPS está sobrecargado.", null, "Fail-open deja pasar el tráfico sin inspeccionar; no desvía el tráfico a FortiSandbox cuando IPS falla.", "Fail-open tiene que ver con la inspección bajo carga, no con el registro; no detiene el registro para ahorrar memoria."]],
  "fg64": ["Una firma de IPS está bloqueando una aplicación interna legítima entre dos hosts conocidos. ¿Cuál es la solución más focalizada?", ["Agregar una exención de IP para esos hosts en esa firma", "Deshabilitar todo el IPS sensor en la política", "Cambiar todas las firmas del sensor a monitor", "Mover el tráfico de la aplicación a una política en modo proxy"], "Una exención de IP mantiene la firma activa para todos los demás. Deshabilitar el sensor o poner todo en monitor elimina la protección de forma amplia.", [null, "Deshabilitar todo el sensor elimina la protección IPS para todo el tráfico de la política, mucho más de lo necesario.", "Poner todas las firmas en monitor deja de bloquear en general y debilita ampliamente la protección.", "Mover el tráfico a una política en modo proxy no se enfoca en la firma con falso positivo y cambia la inspección sin necesidad."]],
  "fg65": ["El SOC quiere impedir que los hosts infectados contacten servidores de comando y control conocidos. ¿Qué opción del IPS sensor ayuda?", ["Bloquear las conexiones salientes a sitios de botnets", "Bloquear URL maliciosas solo en el DNS filter", "Habilitar la acción Warning para todas las categorías", "Configurar el filtro de severidad del sensor en low"], "La opción de botnet C&C del IPS sensor usa la base de datos de botnets de FortiGuard para bloquear las conexiones salientes. Las páginas de advertencia y los filtros de severidad no apuntan al tráfico C&C.", [null, "Un DNS filter bloquea dominios maliciosos al consultarlos, pero la pregunta pide una opción del IPS sensor para el tráfico C&C.", "La acción Warning muestra páginas para continuar en categorías web; no bloquea las conexiones C&C de botnets.", "Un filtro de severidad low selecciona qué firmas aplican; no bloquea específicamente el tráfico de comando y control."]],
  "fg66": ["Un FortiGate tiene dos rutas predeterminadas estáticas: una con distancia 10 y otra con distancia 20. ¿Cuál se usa?", ["Ambas, compartiendo el tráfico entre ellas", "La ruta con distancia 20, porque gana el valor más alto", "La que se configuró más recientemente", "La ruta con distancia 10; la otra espera inactiva"], "Gana la menor distancia administrativa, así que solo la ruta con distancia 10 está en la tabla de enrutamiento activa. La otra permanece en la base de datos de enrutamiento y se activa si se quita la primera.", ["El tráfico no se comparte entre las dos; solo la ruta de menor distancia se instala como activa.", "El valor de distancia más alto pierde; gana la menor distancia administrativa, así que la distancia 20 no se usa.", "Lo reciente no decide la selección de rutas; la decide la distancia administrativa.", null]],
  "fg67": ["Dos rutas predeterminadas estáticas tienen la misma distancia 10, con prioridades 0 y 5. ¿Qué ocurre?", ["Solo la ruta con prioridad 5 se instala en la tabla", "El tráfico se reparte de forma equitativa entre ellas", "Ambas están en la tabla; se usa la ruta con prioridad 0", "Ninguna se instala por un conflicto"], "La misma distancia pone ambas rutas en la tabla activa, y se prefiere la prioridad más baja. Esto mantiene la ruta de respaldo en la tabla, lo que también ayuda a las verificaciones de ruta inversa.", ["La ruta con prioridad 5 no es la única instalada; ambas van a la tabla con la misma distancia.", "Aquí el tráfico no se reparte de forma equitativa; se prefiere el valor de prioridad más bajo, no hay balanceo.", null, "La misma distancia no causa un conflicto que elimine ambas rutas; ambas se instalan."]],
  "fg68": ["Dos rutas predeterminadas estáticas tienen la misma distancia y la misma prioridad. ¿Cómo reenvía el tráfico el FortiGate?", ["Solo por la ruta con la dirección IP de gateway más baja", "Equal-cost multipath, por defecto basado en la IP de origen", "Round robin por paquete entre ambas", "Solo por la primera interfaz de la lista"], "Misma distancia y prioridad crean ECMP, que por defecto reparte las sesiones según la IP de origen. El round robin por paquete no es el valor predeterminado y rompería las sesiones.", ["La IP de gateway más baja no es el desempate; misma distancia y prioridad producen reparto de carga ECMP.", null, "El round robin por paquete no es el valor predeterminado y rompería las sesiones con estado; ECMP por defecto es por IP de origen.", "El tráfico no se fija a la primera interfaz de la lista; ambas se usan mediante ECMP."]],
  "fg69": ["¿Cuándo revisa un FortiGate las policy routes en comparación con la tabla de enrutamiento?", ["Solo después de que una búsqueda en la tabla de enrutamiento no encuentre ninguna coincidencia", "Las policy routes se revisan antes que la tabla de enrutamiento", "Solo para el tráfico que genera el propio FortiGate", "Solo cuando ECMP está habilitado en el FortiGate"], "Las policy routes se evalúan primero; si una coincide, define la ruta. Solo cuando ninguna coincide decide la tabla de enrutamiento.", ["Las policy routes se revisan primero, no solo después de que falle una búsqueda en la tabla de enrutamiento.", null, "Las policy routes también aplican al tráfico de tránsito, no solo al tráfico del propio FortiGate.", "Las policy routes siempre se evalúan primero; no dependen de que ECMP esté habilitado."]],
  "fg70": ["El tráfico que llega por port3 desde 172.20.5.0/24 se descarta, y debug flow muestra una falla de la verificación de ruta inversa. ¿Cuál es la causa probable?", ["No hay ruta de regreso a 172.20.5.0/24 por port3", "A la política de firewall le falta NAT", "La política implicit deny tiene el registro activado", "La subred de origen está en la blocklist de FortiGuard"], "La verificación de reverse path forwarding descarta los paquetes cuando el FortiGate no tiene una ruta de regreso al origen por la interfaz de entrada. Agregar una ruta para esa subred por port3 lo resuelve.", [null, "La falta de NAT causaría un problema de traducción, no un descarte por reverse path forwarding.", "El registro del implicit deny solo guarda los descartes; no causa una falla de RPF.", "Un descarte por RPF se debe a la falta de ruta de regreso, no a que el origen esté en una blocklist de FortiGuard."]],
  "fg71": ["¿Qué comando muestra las rutas estáticas inactivas además de las activas?", ["get router info routing-table all", "get system arp", "diagnose sys session list con un filtro por la ruta", "get router info routing-table database"], "La base de datos de la tabla de enrutamiento incluye las rutas no instaladas, como las de mayor distancia. routing-table all muestra solo las rutas activas.", ["get router info routing-table all muestra solo las rutas activas, no las inactivas de la base de datos.", "get system arp muestra la tabla ARP (IP a MAC), no las rutas estáticas inactivas.", "Una lista de sesiones muestra las sesiones en vivo, no la base de datos de rutas inactivas.", null]],
  "fg72": ["Una sucursal tiene dos ISP. El administrador quiere que se elimine la ruta predeterminada principal si el gateway del ISP deja de responder a los pings. ¿Qué se debe configurar?", ["Una prioridad más baja en la ruta de respaldo", "Una ruta blackhole con distancia 254", "Un link health monitor en la WAN principal", "Una política DoS en la interfaz WAN principal"], "Un link health monitor sondea un destino y elimina la ruta cuando falla, así que el respaldo toma el control. Las prioridades no detectan fallas, y una ruta blackhole descarta el tráfico.", ["Una prioridad más baja en la ruta de respaldo no detecta la falla de la principal; solo define la preferencia entre rutas activas.", "Una ruta blackhole descarta el tráfico; no monitorea el gateway ni elimina la ruta principal cuando falla.", null, "Una política DoS limita el tráfico de ataques; no sondea el gateway ni retira una ruta cuando deja de responder."]],
  "fg73": ["¿Por qué agregar una ruta blackhole para los rangos privados en un sitio con túneles IPsec?", ["Para que los túneles se levanten más rápido después de un reinicio", "Para que ECMP pueda balancear entre túneles", "Para que el tráfico se descarte, en lugar de enviarse a internet, si un túnel está caído", "Para que las actualizaciones de FortiGuard usen el túnel"], "Cuando desaparece la ruta de un túnel, el tráfico hacia las subredes privadas seguiría la ruta predeterminada hacia el ISP. Una ruta blackhole de distancia alta lo descarta en su lugar.", ["Las rutas blackhole no aceleran el establecimiento de los túneles después de un reinicio; solo descartan el tráfico de sus prefijos.", "Las rutas blackhole descartan tráfico; no habilitan el balanceo ECMP entre túneles.", null, "Las rutas blackhole no tienen que ver con dirigir el tráfico de actualizaciones de FortiGuard por el túnel."]],
  "fg74": ["¿Qué mide un performance SLA de SD-WAN?", ["El ancho de banda que usa cada usuario y cada aplicación", "Latencia, jitter y pérdida de paquetes hacia servidores de sondeo", "La cantidad de políticas de firewall por zona", "La calificación de FortiGuard de cada destino"], "Los performance SLA envían sondeos (como ping, HTTP o DNS) por cada miembro y registran la latencia, el jitter y la pérdida. Las reglas de SD-WAN usan estos resultados.", ["El ancho de banda por usuario y por aplicación se mide con traffic shaping/monitoreo, no con un performance SLA.", null, "La cantidad de políticas por zona es un conteo de configuración, no algo que mida un sondeo de SLA.", "Las calificaciones de destinos de FortiGuard provienen del filtrado web, no de los sondeos de performance SLA de SD-WAN."]],
  "fg75": ["El tráfico de voz siempre debe usar el miembro de SD-WAN que tenga en ese momento el menor jitter. ¿Qué estrategia de regla SD-WAN es la adecuada?", ["Best quality, midiendo el jitter", "Lowest cost (SLA)", "Maximize bandwidth (SLA)", "Manual, con el enlace MPLS primero"], "Best quality elige el miembro con el mejor valor de la medida elegida. Lowest cost elige el miembro más barato que cumpla un SLA, no el mejor.", [null, "Lowest cost (SLA) elige el miembro más barato que cumple el SLA, no necesariamente el de menor jitter.", "Maximize bandwidth (SLA) reparte el tráfico entre los miembros que cumplen; no siempre elige el enlace con menor jitter.", "Manual fija el tráfico a un miembro elegido sin importar las mediciones de jitter en vivo."]],
  "fg76": ["El tráfico debe usar la banda ancha barata mientras cumpla el SLA y pasar a MPLS solo cuando la banda ancha no cumpla el SLA. ¿Qué estrategia es la adecuada?", ["Best quality", "Manual", "Maximize bandwidth (SLA)", "Lowest cost (SLA)"], "Lowest cost (SLA) usa el miembro de menor costo que cumple el objetivo del SLA. Best quality movería el tráfico cada vez que MPLS obtuviera una puntuación aunque sea un poco mejor.", ["Best quality cambiaría a MPLS cada vez que obtuviera una puntuación un poco mejor, lo que anula el objetivo de quedarse en la banda ancha barata.", "Manual fija el tráfico a un enlace elegido y no hace failover automáticamente según el cumplimiento del SLA.", "Maximize bandwidth (SLA) balancea la carga entre miembros en lugar de preferir el más barato hasta que no cumpla el SLA.", null]],
  "fg77": ["Después de agregar wan1 y wan2 a SD-WAN, el administrador no puede seleccionar wan1 en una política de firewall. ¿Qué debe referenciar la política?", ["La interfaz loopback", "Una VIP para cada dirección WAN que usan los miembros", "La interfaz de heartbeat de HA", "La zona SD-WAN que contiene a los miembros"], "Una vez que las interfaces son miembros de SD-WAN, las políticas referencian la zona SD-WAN. Los loopbacks, las VIP y los puertos de HA no reemplazan a la zona.", ["Una interfaz loopback no es lo que referencian las políticas de SD-WAN; usan la zona SD-WAN.", "Las VIP son objetos de NAT de destino, no un reemplazo de la referencia a la zona SD-WAN en una política.", "La interfaz de heartbeat de HA es para clústeres, no para dirigir el tráfico de usuarios en una política de firewall.", null]],
  "fg78": ["Los miembros, el SLA y las reglas de SD-WAN están configurados, pero el tráfico a internet sigue fallando. Se eliminaron las rutas predeterminadas estáticas antiguas de wan1 y wan2. ¿Qué falta?", ["Una policy route para cada subred de usuarios de la LAN", "Un segundo performance SLA", "Una ruta predeterminada estática que use la zona SD-WAN", "Un IP pool en la zona SD-WAN"], "Las reglas de SD-WAN solo dirigen el tráfico que la tabla de enrutamiento ya envía a SD-WAN, así que se necesita una ruta que apunte a la zona. Los SLA adicionales o los IP pools no agregan una ruta.", ["Las policy routes por subred no son la pieza que falta; SD-WAN sigue necesitando una ruta que envíe el tráfico a la zona.", "Un segundo performance SLA no agrega una ruta; la tabla de enrutamiento sigue sin camino hacia la zona SD-WAN.", null, "Un IP pool proporciona direcciones de NAT de origen; no crea la ruta predeterminada que requiere SD-WAN."]],
  "fg79": ["¿Qué puertos deben estar abiertos entre dos pares IPsec cuando uno de ellos está detrás de un dispositivo NAT?", ["TCP 443 y TCP 8443", "UDP 500 y UDP 4500", "UDP 1701 y TCP 1723", "TCP 500 y TCP 4500"], "IKE usa UDP 500, y NAT traversal mueve el tráfico a UDP 4500. L2TP y PPTP usan 1701 y 1723.", ["TCP 443/8443 son puertos de HTTPS/SSL VPN, no los puertos de IKE y NAT-T que usa IPsec.", null, "UDP 1701 y TCP 1723 son L2TP y PPTP, no IKE/NAT-T de IPsec.", "IKE y NAT-T usan UDP 500 y UDP 4500, no TCP 500/4500."]],
  "fg80": ["La fase 1 de un túnel sitio a sitio se levanta, pero la fase 2 nunca lo hace. ¿Cuál es la causa MÁS probable?", ["Los selectores o las propuestas de la fase 2 no coinciden", "La clave precompartida es incorrecta en uno de los pares", "El ISP bloquea UDP 500", "Los pares usan versiones distintas de IKE"], "Que la fase 1 funcione demuestra que la clave, la versión de IKE y la alcanzabilidad están bien. La fase 2 falla cuando las subredes (selectores) o las propuestas de cifrado difieren entre los pares.", [null, "Una clave precompartida incorrecta haría fallar la fase 1; como la fase 1 está activa, la clave ya es correcta.", "Si UDP 500 estuviera bloqueado, la fase 1 tampoco podría completarse; pero la fase 1 está activa, así que no está bloqueado.", "Versiones de IKE distintas impedirían que se formara la fase 1; que la fase 1 funcione lo descarta."]],
  "fg81": ["¿Por qué normalmente se prefiere una VPN IPsec basada en rutas (interface-mode) en lugar de una basada en políticas?", ["Crea una interfaz de túnel que se puede usar en rutas y políticas", "No necesita ninguna política de firewall", "Cifra el tráfico con algoritmos más fuertes", "Solo se puede construir con IKEv1"], "Las VPN basadas en rutas crean una interfaz virtual, así que las rutas (incluidas las de enrutamiento dinámico y las de respaldo) y las políticas normales pueden usarla. La fortaleza del cifrado es la misma en ambas.", [null, "Las VPN basadas en rutas siguen necesitando políticas de firewall para el tráfico del túnel; no eliminan las políticas.", "La fortaleza del cifrado es idéntica en las VPN basadas en rutas y en políticas; esa no es la ventaja.", "Las VPN basadas en rutas admiten IKEv1 e IKEv2; no se limitan a IKEv1."]],
  "fg82": ["Un nuevo túnel basado en rutas aparece como activo, pero no pasa tráfico entre las dos LAN. ¿Qué es lo que MÁS probablemente falta?", ["Una segunda fase 1 en modo agresivo", "Una VIP para cada host remoto", "NAT-T deshabilitado en ambos pares", "Una ruta por el túnel y políticas entre la LAN y el túnel"], "Un túnel activo aún necesita una ruta hacia la subred remota a través de la interfaz de túnel y políticas de firewall en ambas direcciones. Las VIP y los cambios de NAT-T no son necesarios.", ["No se necesita una segunda fase 1 en modo agresivo; el túnel está activo, pero le faltan la ruta y las políticas.", "Una VIP por host remoto es NAT de destino y no es lo que necesita un túnel basado en rutas para pasar tráfico de la LAN.", "No es necesario deshabilitar NAT-T; las piezas que faltan son la ruta por el túnel y las políticas.", null]],
  "fg83": ["La oficina central tiene dos ISP y quiere que los túneles de las sucursales hagan failover automáticamente. ¿Qué diseño es el adecuado?", ["Un túnel basado en políticas con dos selectores de fase 2", "Dos túneles con rutas idénticas y DPD desactivado", "Dos túneles basados en rutas con distintas distancias de ruta y DPD", "Un túnel cuyo par se cambia a mano"], "Dos túneles (uno por ISP) con rutas preferida y de respaldo dan failover, y DPD detecta el túnel caído para que se retire su ruta. Sin DPD, el túnel caído podría seguir apareciendo activo.", ["Un solo túnel basado en políticas con dos selectores no ofrece failover a nivel de ISP entre dos caminos.", "Rutas idénticas con DPD desactivado no dan un camino preferido y de respaldo claro y no pueden detectar un túnel caído para hacer failover.", null, "Cambiar el par a mano no es un failover automático; requiere intervención humana en cada caída."]],
  "fg84": ["¿Qué hace dead peer detection (DPD)?", ["Cifra el tráfico dos veces para impedir ataques de repetición de pares externos", "Detecta un par que no responde para que el túnel se dé de baja", "Bloquea los pares que aparecen en las blocklists de FortiGuard", "Renueva la clave de fase 2 después de cada paquete"], "DPD envía sondeos y da de baja el túnel cuando el par deja de responder, para que las rutas puedan pasar a un respaldo. No afecta el cifrado.", ["Cifrar el tráfico dos veces no es lo que hace DPD; detecta pares que no responden para dar de baja el túnel.", null, "DPD no consulta las blocklists de FortiGuard; sondea al par configurado para ver si responde.", "DPD no vuelve a generar la clave de la fase 2 después de cada paquete; PFS y los temporizadores de rekey manejan la renovación de claves por separado."]],
  "fg85": ["Cinco sitios deben conectarse en una malla completa de túneles IPsec. ¿Cuántos túneles se necesitan?", ["5", "10", "20", "25"], "Una malla completa necesita n(n−1)/2 túneles, y 5×4/2 = 10. Hub and spoke necesitaría solo 4.", ["5 sería la cuenta solo si cada sitio necesitara un túnel; una malla completa necesita n(n-1)/2, que es 10.", null, "20 cuenta los túneles dos veces; cada par comparte un túnel, lo que da 10, no 20.", "25 es 5 al cuadrado y cuenta pares de un sitio consigo mismo, que no existen; el total correcto de la malla completa es 10."]],
  "fg86": ["En una VPN hub and spoke, los spokes deben construir túneles directos entre sí bajo demanda en lugar de enviar todo el tráfico por el hub. ¿Qué se debe usar?", ["ADVPN", "Una malla completa de túneles estáticos", "VPN basada en políticas en el hub", "SSL VPN en modo web"], "ADVPN permite que los spokes creen túneles de atajo bajo demanda. Una malla estática completa funciona, pero hay que construirla y mantenerla a mano.", [null, "Una malla estática completa da caminos directos, pero hay que construirla y mantenerla a mano, a diferencia de ADVPN bajo demanda.", "Una VPN basada en políticas en el hub no crea túneles de atajo bajo demanda entre spokes.", "SSL VPN en modo web es acceso de usuarios remotos a recursos, no atajos IPsec dinámicos entre spokes."]],
  "fg87": ["Una sucursal obtiene una IP pública dinámica de su ISP, mientras que la oficina central tiene una IP estática. ¿Cómo se debe configurar la fase 1?", ["Ambos usan pares estáticos con la IP actual del otro", "Ambos usan pares dial-up para que cualquiera pueda iniciar el túnel", "La sucursal usa dial-up y la oficina central usa estático", "La oficina central usa un par dial-up (dinámico); la sucursal apunta a la oficina central"], "El lado con dirección desconocida debe iniciar el túnel, así que la oficina central lo acepta como par dial-up y la sucursal usa la IP estática de la oficina central. Dos pares dial-up nunca podrían encontrarse.", ["La oficina central no conoce la IP de la sucursal, así que no puede configurarse con la dirección actual de la sucursal como par estático.", "Dos pares dial-up esperan ambos a ser contactados y nunca iniciarían, así que el túnel nunca podría formarse.", "Esto invierte los roles: la sucursal con IP dinámica debe iniciar, y la oficina central debe aceptarla como par dial-up.", null]],
  "fg88": ["¿Qué comandos muestran los mensajes de negociación IKE en tiempo real?", ["get vpn ipsec stats crypto y luego execute ping", "diagnose sys session list y luego diagnose debug reset", "diagnose debug application ike -1 y luego diagnose debug enable", "get router info routing-table all y luego diagnose debug disable"], "El debug de IKE con nivel -1 y la salida de debug habilitada muestran los pasos de la negociación. Las listas de sesiones y las tablas de enrutamiento no muestran mensajes IKE.", ["get vpn ipsec stats crypto muestra contadores criptográficos, no los mensajes de negociación IKE en vivo.", "Una lista de sesiones y debug reset no muestran los pasos de la negociación IKE en tiempo real.", null, "La tabla de enrutamiento y deshabilitar el debug no muestran los mensajes de negociación IKE."]],
  "fg89": ["¿Qué hace habilitar perfect forward secrecy (PFS) en la fase 2?", ["Usa la clave de la fase 1 para todas las claves de la fase 2", "Envía el tráfico por el túnel sin cifrar como prueba de conectividad", "Ejecuta un nuevo intercambio Diffie-Hellman para cada clave de la fase 2", "Permite a los pares omitir la fase 1 al reconectarse"], "PFS genera material de claves nuevo, así que comprometer una clave no expone las demás. Sin PFS, las claves de la fase 2 provienen del material de la fase 1.", ["Reutilizar la clave de la fase 1 para todas las claves de la fase 2 es lo que ocurre sin PFS, lo contrario de habilitarlo.", "PFS no envía tráfico sin cifrar; fortalece el manejo de claves, y el túnel sigue cifrado.", null, "PFS no permite omitir la fase 1 al reconectarse; agrega un intercambio DH nuevo para las claves de la fase 2."]],
  "fg90": ["¿Qué comando lista los gateways IKE (fase 1) actuales y su estado?", ["get system interface physical", "diagnose vpn ike gateway list", "diagnose sys ha status", "get router info bgp summary"], "diagnose vpn ike gateway list muestra cada gateway de fase 1, su estado y la configuración negociada. Los demás muestran interfaces, HA y BGP.", ["get system interface physical muestra detalles de las interfaces físicas, no el estado de los gateways IKE de fase 1.", null, "diagnose sys ha status informa el estado del clúster de HA, no los gateways IKE.", "get router info bgp summary muestra los pares BGP, no los gateways IKE de fase 1 de IPsec."]],
  "x1": ["Un administrador inició sesión en la unidad primaria de un clúster FGCP y necesita ejecutar diagnósticos en la CLI de la unidad secundaria, que no tiene IP de administración propia. ¿Qué debe usar?", ["get system ha status", "diagnose sys ha checksum cluster", "execute ha manage <index> <admin>", "execute ha synchronize start"], "execute ha manage abre una sesión de CLI en otro miembro del clúster a través del enlace de HA, usando el índice del miembro y un nombre de administrador. get system ha status solo informa el estado del clúster; no da un shell en la secundaria.", ["Esto solo informa el estado del clúster y los detalles de los miembros; no abre una sesión en la secundaria.", "Esto compara los checksums de configuración entre miembros; no da una CLI en otra unidad.", null, "Esto inicia una sincronización de configuración entre miembros; no te inicia sesión en la secundaria."]],
  "x2": ["get system performance status muestra el uso de CPU fijo cerca del 95%. ¿Qué comando debe ejecutar a continuación el administrador para ver qué proceso está usando la CPU?", ["diagnose sys session stat", "get system status", "diagnose debug flow trace start 10", "diagnose sys top"], "diagnose sys top lista los procesos en ejecución ordenados por uso de CPU y memoria, así que muestra qué daemon está ocupado. diagnose sys session stat da conteos de sesiones, que pueden sugerir la carga pero no nombran el proceso.", ["Esto muestra conteos de sesiones, que pueden sugerir la carga pero no nombran el proceso ocupado.", "Esto muestra detalles de firmware, serial y modo, no el uso de CPU por proceso.", "Debug flow traza cómo se manejan los paquetes; no ordena los procesos por CPU.", null]],
  "x3": ["Un proveedor de servicios administrados quiere alojar los firewalls de tres clientes pequeños en un solo FortiGate. Los administradores de cada cliente deben ver solo sus propias políticas, rutas y registros. ¿Qué es lo MEJOR?", ["Tres secciones de políticas, cada una con sus propios objetos de dirección", "Modo multi-VDOM con una VDOM por cliente y los administradores asignados a ella", "Tres perfiles de administrador de solo lectura, todos trabajando dentro de una VDOM root compartida", "Un clúster de HA con un miembro del clúster por cliente"], "Las VDOM dividen un FortiGate en instancias separadas con sus propias políticas, rutas y registros, y los administradores se pueden limitar a su VDOM. Las secciones de políticas en una VDOM siguen compartiendo una tabla de enrutamiento y todos los administradores verían la configuración de todos los clientes.", ["Las secciones de políticas en una VDOM siguen compartiendo el enrutamiento y cada administrador vería la configuración de todos los clientes.", null, "Los perfiles de administrador en una VDOM limitan los permisos, no qué objetos de qué cliente puede ver cada administrador.", "Los miembros de HA reflejan una sola configuración; no pueden contener firewalls separados por cliente."]],
  "x4": ["El tráfico debe pasar entre la VDOM Sales y la VDOM Shared en el mismo FortiGate sin salir del equipo por un cable. ¿Qué debe crear el administrador?", ["Un inter-VDOM link, más rutas y políticas en ambas VDOM", "Una ruta estática solo en la VDOM root", "Un puerto físico asignado a ambas VDOM al mismo tiempo", "Un nuevo perfil de administrador con acceso a ambas VDOM"], "Un inter-VDOM link es un par de interfaces virtuales que une dos VDOM; cada lado sigue necesitando rutas y políticas de firewall. Una interfaz solo puede pertenecer a una VDOM, así que no es posible compartir un puerto físico entre ellas.", [null, "Una ruta en la VDOM root no puede mover tráfico entre otras dos VDOM sin un enlace que las una.", "Una interfaz pertenece exactamente a una VDOM, así que no puede compartirse de esta forma.", "Los derechos de administrador controlan quién puede configurar las VDOM; no transportan tráfico entre ellas."]],
  "x5": ["HA override está habilitado en ambos miembros del clúster. La unidad A tiene prioridad 200, la unidad B tiene prioridad 100, ambas tienen todas las interfaces monitoreadas activas y B tiene el HA uptime más largo. ¿Qué unidad pasa a ser primaria?", ["La unidad B, porque el HA uptime siempre se compara primero", "La unidad B, porque override favorece a la unidad que arrancó primero", "La unidad A, porque override pone la prioridad antes que el uptime", "La unidad con el número de serie más alto, como desempate"], "Con override habilitado, el orden es interfaces monitoreadas, luego prioridad, luego uptime y luego serial, así que gana la unidad A, de mayor prioridad. El uptime antes que la prioridad es el orden predeterminado solo cuando override está deshabilitado.", ["El uptime va antes que la prioridad solo cuando override está deshabilitado, que no es el caso aquí.", "Override hace que cuente más la prioridad, no el orden de arranque; el orden de arranque no es una regla de elección.", null, "El número de serie es solo el último desempate, y la prioridad ya decide esta elección."]],
  "x6": ["¿Por qué Fortinet recomienda al menos dos enlaces de heartbeat para un clúster FGCP, conectados directamente o en una red aislada?", ["Para duplicar el ancho de banda solo para la sincronización de sesiones", "Para que la falla de un enlace de heartbeat no deje a ambas unidades actuando como primarias", "Porque FGCP necesita un enlace de heartbeat separado para cada VDOM", "Para que cada miembro del clúster se pueda administrar desde su propia subred de administración"], "Si fallan todos los enlaces de heartbeat, cada unidad cree que la otra desapareció y ambas pasan a primarias (split brain); un segundo enlace elimina ese punto único de falla. El ancho de banda de sincronización es un beneficio secundario, no la razón principal.", ["El ancho de banda de sincronización es un beneficio secundario; el riesgo principal que se atiende es el split brain tras la falla de un solo enlace.", null, "Los enlaces de heartbeat los comparten todas las VDOM; FGCP no necesita uno por VDOM.", "Los enlaces de heartbeat transportan tráfico de HA, no el acceso de administración por unidad desde distintas subredes."]],
  "x7": ["En un clúster activo-pasivo, port1 es una interfaz monitoreada. Se desconecta el cable del port1 del primario, mientras que el port1 del secundario sigue conectado. ¿Qué ocurre?", ["Nada, porque solo la pérdida de heartbeat puede desencadenar un failover de HA", "El clúster deshabilita port1 en ambos miembros para mantenerse sincronizado", "El primario se reinicia para eliminar la falla de la interfaz", "El secundario toma el control porque tiene más puertos monitoreados activos"], "Las interfaces monitoreadas son el primer criterio de elección, así que la unidad con más puertos monitoreados conectados pasa a primaria. La pérdida de heartbeat no es el único desencadenante de failover; la falla de enlace en un puerto monitoreado es justamente la razón para monitorearlo.", ["La falla de una interfaz monitoreada es un desencadenante de failover, no solo la pérdida de heartbeat.", "El clúster no apaga los puertos en ambas unidades; en su lugar mueve el rol de primario.", "El primario no se reinicia por una falla de enlace; cede el rol de primario.", null]],
  "x8": ["FortiAnalyzer en el Security Fabric marca un host interno como comprometido. El equipo quiere que el FortiGate aísle ese host automáticamente. ¿Qué automation stitch es el adecuado?", ["Desencadenador Compromised Host con una acción de cuarentena o IP ban", "Desencadenador Schedule que ejecute un script de CLI cada hora", "Desencadenador de cambio de configuración con una acción de correo", "Desencadenador de failover de HA que envíe un webhook al SOC"], "El desencadenador Compromised Host se activa con los indicadores de compromiso de FortiAnalyzer y puede ejecutar una acción de aislamiento como access layer quarantine o IP ban. Un script de CLI programado no está vinculado a la detección y no sabría qué host aislar.", [null, "Un script programado no está vinculado a la detección y no sabría qué host aislar.", "Un desencadenador de cambio de configuración se activa con ediciones de administradores, no con una alerta de host comprometido.", "El failover de HA no tiene relación con el compromiso de un host, así que este stitch nunca se activaría para ello."]],
  "x9": ["Un administrador quiere revisar las conexiones hechas al propio FortiGate, como intentos de SSH o HTTPS contra la IP de la WAN. ¿Qué registro debe revisar?", ["Registro de tráfico forward", "Registro de seguridad IPS", "Registro de tráfico local", "Registro de tráfico del sniffer"], "Los registros de tráfico local guardan las sesiones hacia y desde el propio FortiGate, como el acceso de administración. El registro de tráfico forward cubre las sesiones que pasan a través del FortiGate entre interfaces, no el tráfico dirigido a él.", ["Los registros de tráfico forward cubren las sesiones que pasan por el equipo, no las sesiones dirigidas a él.", "Los registros de IPS guardan coincidencias de firmas, no cada conexión a la interfaz de administración.", null, "Los registros de tráfico del sniffer se relacionan con interfaces one-arm sniffer, no con conexiones de administración."]],
  "x10": ["Un administrador ejecuta diagnose sniffer packet any 'host 10.1.1.5' 1 y ve paquetes, pero no puede saber qué interfaz usó cada paquete. ¿Qué debe cambiar?", ["Reemplazar any por el nombre de la interfaz WAN", "Usar verbosity 4, que imprime el nombre de la interfaz", "Agregar -i después del filtro para incluir datos de la interfaz", "Ejecutar diagnose debug enable antes de iniciar el sniffer"], "Verbosity 4 imprime los encabezados de los paquetes junto con el nombre de la interfaz, que es lo que se necesita al capturar en any. Indicar una sola interfaz ocultaría los paquetes de las demás, así que no se podría seguir el camino a través del equipo.", ["Indicar una sola interfaz oculta los paquetes de las demás, así que se pierde el camino a través del equipo.", null, "El sniffer no tiene una opción -i; los nombres de las interfaces provienen del nivel de verbosity.", "debug enable es para salidas de debug como los flow traces; el sniffer imprime sin él."]],
  "x11": ["Una nueva regla de auditoría indica que los inicios de sesión de administradores deben usar un segundo factor además de la contraseña. ¿Qué función de FortiGate cumple esto?", ["Trusted hosts limitados a la estación de trabajo de cada administrador", "Una política de contraseñas de administrador más fuerte con vencimiento", "Un perfil de administrador limitado a acceso de solo lectura", "Autenticación de dos factores en cada cuenta de administrador"], "FortiOS admite autenticación de dos factores para cuentas de administrador, por ejemplo con FortiToken o códigos por correo. Los trusted hosts restringen desde dónde se inicia sesión, pero no agregan un segundo factor de autenticación.", ["Los trusted hosts restringen desde dónde se inicia sesión; no son un segundo factor.", "Una contraseña más fuerte sigue siendo un solo factor, así que no cumple la regla.", "Los perfiles de solo lectura limitan lo que pueden cambiar los administradores, no cómo se autentican.", null]],
  "x12": ["Se perdió la única contraseña de super_admin. El administrador tiene acceso por consola y no quiere hacer un restablecimiento de fábrica. ¿Qué opción de recuperación documentada existe, si no se ha deshabilitado?", ["Iniciar sesión como maintainer en la consola poco después de un reinicio en frío", "Iniciar sesión como root por SSH, usando el número de serie del equipo como contraseña", "Usar el enlace de contraseña olvidada en la página de inicio de sesión de la GUI", "Ejecutar execute factoryreset keepvmlicense desde la consola"], "La cuenta maintainer puede restablecer las contraseñas de administrador desde la consola durante un breve período después de un reinicio en frío, salvo que se haya deshabilitado. Un comando de restablecimiento de fábrica borra la configuración, que es justo lo que el administrador quiere evitar.", [null, "En un FortiGate no existe un inicio de sesión root por SSH que use el número de serie.", "La GUI de FortiGate no tiene un enlace de autoservicio de contraseña olvidada para administradores.", "Un restablecimiento de fábrica borra la configuración, lo que el administrador quiere evitar."]],
  "x13": ["Un FortiGate-VM en una nube pública debe permitir tráfico hacia servidores web con autoescalado, cuyas IP cambian con frecuencia. ¿Cuál es la MEJOR forma de referenciarlos en las políticas?", ["Un objeto de dirección /32 estático para cada servidor, actualizado a mano", "Un objeto de dirección de geografía para el país de la región de la nube", "Una dirección dinámica de un SDN connector, filtrada por etiquetas", "Un objeto FQDN para el sitio web público del proveedor de nube"], "Un SDN (Fabric) connector lee los metadatos de la nube y mantiene un objeto de dirección dinámico con las IP actuales de las instancias que tienen una etiqueta. Los objetos /32 actualizados a mano se quedan atrás cada vez que las instancias escalan hacia arriba o hacia abajo.", ["Los objetos editados a mano se quedan atrás cada vez que las instancias escalan hacia arriba o hacia abajo.", "Un objeto de geografía coincidiría con las IP de todo el país, lo cual es demasiado amplio.", null, "Las IP del sitio web del proveedor no tienen nada que ver con las instancias propias del cliente."]],
  "x14": ["¿Qué significa que un FortiGate entre en memory conserve mode?", ["La temperatura de la CPU superó el umbral de control de los ventiladores", "El disco de registros se llenó, así que todo el registro se detuvo", "Hay demasiadas sesiones de administrador abiertas al mismo tiempo", "El uso de memoria superó un umbral, así que limita el trabajo nuevo"], "Conserve mode se activa cuando el uso de memoria supera un umbral, y el equipo limita las sesiones nuevas y la inspección para protegerse. No tiene que ver con la temperatura ni con un disco de registros lleno; esos generan sus propios eventos.", ["Los problemas de temperatura generan sus propias alertas de hardware; conserve mode tiene que ver con la memoria.", "Un disco de registros lleno provoca eventos de manejo de registros, no memory conserve mode.", "Las sesiones de administrador no son lo que mide conserve mode; vigila el uso de memoria.", null]],
  "x15": ["Un administrador arrastra la política con ID 12 de la tercera posición de la lista a la primera. ¿Qué cambia?", ["El policy ID cambia a 1", "Cambia su secuencia; el ID sigue siendo 12", "Se hace una copia y el ID 12 se queda en su lugar", "Todos los policy IDs se renumeran según el orden de la lista"], "El policy ID es un identificador fijo, mientras que la secuencia es la posición que se usa para la coincidencia de arriba hacia abajo, así que moverla solo cambia la secuencia. Los ID nunca se renumeran cuando se mueven las políticas.", ["El ID es una etiqueta fija y no cambia cuando se mueve la política.", null, "Mover una política no la copia; la misma política solo cambia de posición.", "Los ID nunca se renumeran; solo cambia el orden que se usa para la coincidencia."]],
  "x16": ["Sin enviar tráfico de prueba, un administrador quiere saber qué política coincidiría con TCP 443 desde 10.1.1.20 hacia 8.8.8.8. ¿Qué debe usar?", ["diagnose sniffer packet con un filtro de host", "El panel FortiView de orígenes", "El registro de tráfico forward filtrado por origen", "La herramienta policy lookup en la página de políticas"], "La herramienta policy lookup recibe una interfaz, un protocolo, un origen y un destino, y resalta la política que coincidiría. El sniffer y los registros solo muestran tráfico que realmente se envió.", ["El sniffer solo muestra tráfico que realmente se envía, lo que el administrador quiere evitar.", "FortiView resume tráfico pasado y no simula la coincidencia de una política.", "Los registros muestran solo sesiones que ya ocurrieron, no una hipotética.", null]],
  "x17": ["Un portal web público publicado con una VIP debe aceptar conexiones solo de clientes ubicados en Canadá. ¿Cuál es la forma más limpia de hacerlo?", ["Usar una dirección de geografía de Canadá como origen de la política de la VIP", "Agregar una entrada de filtro de URL estático para los dominios .ca", "Crear un DNS filter que permita solo dominios canadienses", "Agregar un IP pool one-to-one para los rangos de origen canadienses"], "Los objetos de dirección de geografía coinciden con las IP de origen según los datos de geolocalización de FortiGuard, así que usar uno como origen limita la política de la VIP a clientes canadienses. Los filtros de URL y DNS miran los nombres de destino, no dónde está el cliente.", [null, "Los filtros de URL miran la URL de destino, no dónde está ubicado el cliente.", "Los DNS filters revisan los nombres que se consultan, no el país del cliente.", "Los IP pools cambian las direcciones de origen del tráfico saliente; no filtran clientes."]],
  "x18": ["Un proveedor hace NAT a miles de suscriptores y quiere una entrada de registro cada vez que a un suscriptor se le asigna un conjunto de puertos públicos, en lugar de una entrada por cada sesión. ¿Qué opción de NAT de origen es la adecuada?", ["Un pool overload compartido por todos los usuarios", "Un pool one-to-one del tamaño de la cantidad de usuarios", "Un pool de port block allocation", "La dirección de la interfaz de salida"], "Port block allocation le da a cada usuario un bloque de puertos en una IP pública y registra la asignación del bloque, lo que reduce mucho el volumen de registros. Un pool overload simple asigna puertos por sesión, así que rastrear usuarios requiere registros por sesión.", ["Un pool overload asigna puertos por sesión, así que necesita registros por sesión para rastrear usuarios.", "Los pools one-to-one necesitan una IP pública por usuario, lo cual es imposible para miles de suscriptores.", null, "El NAT de interfaz es un overload simple sobre una IP, registrado por sesión."]],
  "x19": ["El área legal quiere determinar qué host interno usó una IP pública y un puerto dados mediante una fórmula fija, incluso sin ningún registro de NAT. ¿Qué tipo de IP pool lo permite?", ["Fixed port range, que asigna rangos internos a rangos externos", "Overload, con ARP reply desactivado en el pool", "Port block allocation, con un tamaño de bloque pequeño", "Central SNAT usando solo la dirección de la interfaz"], "Un pool fixed port range asigna cada IP interna a una IP pública y un rango de puertos conocidos, así que el mapeo se puede calcular sin registros. Port block allocation asigna bloques de forma dinámica, así que sigue dependiendo de sus registros de asignación.", [null, "Overload asigna puertos de forma dinámica, así que el mapeo no se puede determinar sin registros.", "PBA entrega bloques de forma dinámica y depende de sus registros de asignación para rastrear usuarios.", "El NAT de interfaz asigna puertos de forma dinámica por sesión, así que también necesita registros."]],
  "x20": ["Un IP pool overload usa 198.51.100.10, que no está en la subred de la interfaz WAN. Las sesiones salientes salen, pero las respuestas nunca vuelven. ¿Qué se necesita?", ["Habilitar ARP reply en el IP pool", "Cambiar el tipo de pool a one-to-one", "Crear una VIP para 198.51.100.10", "Una ruta en el equipo de arriba (upstream) hacia la WAN para la IP del pool"], "Cuando las direcciones del pool están fuera de la subred de la WAN, el router de arriba debe enrutarlas hacia la dirección WAN del FortiGate. ARP reply solo ayuda cuando la dirección del pool está en la subred conectada, donde el router haría ARP por ella.", ["ARP reply solo ayuda cuando la IP del pool está en la subred conectada, y no es el caso.", "Cambiar el tipo de pool no le dice al router de arriba dónde está la dirección.", "Una VIP maneja NAT de destino entrante y seguiría necesitando la misma ruta en el equipo de arriba.", null]],
  "x21": ["Tres VIP comparten una IP pública, pero usan puertos distintos para llegar a tres servidores internos. ¿Cómo puede una sola política referenciar las tres?", ["Fusionarlas en una VIP con tres IP mapeadas", "Habilitar central SNAT para que las VIP apliquen por sí solas", "Agregarlas a un VIP group y usarlo como destino", "Poner los tres servidores en un grupo de direcciones"], "Un VIP group agrupa varias VIP para que una política las use todas como destino. Un grupo de direcciones con las IP reales de los servidores no hace NAT de destino, así que el tráfico entrante hacia la IP pública no se traduciría.", ["Una VIP asigna una configuración de dirección y puerto externos; tres mapeos de puertos distintos necesitan tres VIP.", "Central SNAT maneja el NAT de origen; no aplica las VIP al tráfico por sí solo.", null, "Un grupo de direcciones con las IP reales de los servidores no hace NAT de destino para la IP pública."]],
  "x22": ["Los usuarios se autentican contra un servidor RADIUS. Solo los que el servidor ubica en 'Contractors' deben coincidir con una política restringida. ¿Cómo conoce el FortiGate su grupo?", ["El servidor devuelve un atributo Fortinet-Group-Name que coincide con el grupo", "El FortiGate consulta Active Directory por LDAP justo después de cada inicio de sesión RADIUS", "El secreto compartido de RADIUS se configura con el nombre del grupo", "Cada contratista se crea en su lugar como usuario local"], "Un grupo de usuarios de FortiGate puede coincidir con el atributo de proveedor Fortinet-Group-Name que devuelve RADIUS, así que el servidor decide la pertenencia al grupo. El secreto compartido solo protege el intercambio RADIUS y no lleva información del usuario.", [null, "El FortiGate no agrega una consulta LDAP a un inicio de sesión RADIUS para la coincidencia de grupos.", "El secreto compartido solo protege el intercambio RADIUS y no lleva datos de grupo.", "Los usuarios locales evitarían el servidor RADIUS que se supone que decide la pertenencia."]],
  "x23": ["Una política requiere autenticación activa. Los usuarios que abren un navegador reciben una página de inicio de sesión, pero a los que solo inician un cliente SSH nunca se les solicita. ¿Por qué?", ["La política implicit deny siempre descarta SSH", "Solo protocolos como HTTP, HTTPS, FTP y Telnet desencadenan la solicitud", "Los clientes SSH solo se pueden identificar cuando FSSO se ejecuta en modo polling en los DC", "El tiempo de espera de autenticación está configurado demasiado corto"], "La autenticación activa solo pide credenciales en protocolos que pueden llevar un intercambio de inicio de sesión, como HTTP, HTTPS, FTP y Telnet; los usuarios deben autenticarse primero de esa forma. El tiempo de espera controla cuánto dura el inicio de sesión, no si aparece una solicitud.", ["El implicit deny solo descarta tráfico sin coincidencia; aquí la política coincide, pero requiere inicio de sesión.", null, "FSSO es autenticación pasiva y no tiene relación con que no aparezcan las solicitudes activas.", "El tiempo de espera controla cuánto dura el inicio de sesión, no si se muestra una solicitud."]],
  "x24": ["¿Qué comando lista los usuarios que el FortiGate conoce actualmente a partir de su FSSO collector agent?", ["diagnose firewall auth clear", "get user fsso", "diagnose sys session list", "diagnose debug authd fsso list"], "diagnose debug authd fsso list muestra las entradas de inicio de sesión de FSSO (usuario, IP, grupos) recibidas del collector. diagnose firewall auth clear eliminaría a los usuarios autenticados en lugar de listarlos.", ["Este comando elimina a los usuarios autenticados; no lista los inicios de sesión de FSSO.", "Esto muestra la configuración del agente FSSO, no la lista de usuarios conectados.", "La lista de sesiones muestra sesiones, no los mapeos de usuario a IP de FSSO.", null]],
  "x25": ["Los usuarios de firewall se quejan de que se les cierra la sesión tras poco tiempo sin tráfico y deben volver a iniciar sesión. ¿Qué configuración controla esto?", ["El tiempo de espera de autenticación de firewall y su tipo", "El tiempo de inactividad de administradores en la configuración del sistema", "El session TTL de la política de firewall", "El tiempo de concesión DHCP de la interfaz LAN"], "El tiempo de espera de autenticación de usuarios de firewall (de tipo idle, hard o new-session) decide cuándo vence el inicio de sesión de un usuario. El tiempo de inactividad de administradores aplica solo a las sesiones de GUI y CLI de administradores, no a los usuarios de firewall.", [null, "El tiempo de inactividad de administradores aplica solo a las sesiones de GUI y CLI de administradores.", "El session TTL controla las sesiones inactivas en la tabla de sesiones, no la duración del inicio de sesión del usuario.", "El tiempo de concesión DHCP controla las concesiones de direcciones y no tiene nada que ver con los inicios de sesión de usuarios."]],
  "x26": ["El acceso entrante a un servidor de estado debe permitirse solo desde un proveedor SaaS de monitoreo que tiene una entrada en la Internet Service Database y cambia sus IP con frecuencia. ¿Qué debe usar la política?", ["Una dirección de geografía del país de origen del proveedor", "Un objeto FQDN para el sitio web de marketing del proveedor", "La entrada ISDB del proveedor como origen de la política", "Un FQDN comodín para el dominio principal del proveedor"], "FortiGuard mantiene actualizada una entrada ISDB con las IP del proveedor, y se puede usar como origen de una política. Un FQDN del sitio web resuelve a servidores web, que normalmente no son las direcciones desde las que vienen los sondeos de monitoreo.", ["Las IP de todo un país son demasiado amplias y admitirían a cualquiera ubicado ahí.", "Las direcciones del sitio web normalmente no son las direcciones desde las que se conectan los sondeos del proveedor.", null, "Los FQDN comodín dependen de las consultas DNS que ve el FortiGate, no de los orígenes de los sondeos."]],
  "x27": ["Central SNAT está habilitado. El tráfico saliente de una nueva subred DMZ sale del FortiGate con IP de origen privadas. ¿Cuál es la causa MÁS probable?", ["La interfaz DMZ no tiene un rol de interfaz configurado", "La política de la DMZ usa una VIP como destino", "Central SNAT solo traduce tráfico IPv6", "Ninguna entrada de central SNAT coincide con la subred DMZ"], "Con central SNAT, la traducción proviene de una tabla SNAT separada que se evalúa de arriba hacia abajo; si ninguna entrada coincide con la subred nueva, el tráfico sale sin traducir. El rol de interfaz solo cambia valores predeterminados de la GUI y no afecta el NAT.", ["Los roles de interfaz solo cambian valores predeterminados de la GUI; no afectan el NAT de origen.", "Una VIP es NAT de destino para tráfico entrante y no hace que se omita el SNAT saliente.", "Central SNAT funciona con IPv4; no se limita a IPv6.", null]],
  "x28": ["Con deep inspection, el certificado de un servidor no es de confianza. ¿Por qué el FortiGate lo vuelve a firmar con una CA no confiable separada en lugar de su CA de inspección normal?", ["Para acelerar el handshake TLS con el cliente", "Para que el navegador siga advirtiendo que el certificado real no era de confianza", "Porque la CA normal no puede firmar certificados vencidos", "Para que el servidor de destino vea exactamente qué usuario hizo la conexión"], "Volver a firmar con una CA en la que los clientes no confían mantiene la advertencia del navegador, así que no se lleva a los usuarios a confiar en un servidor malo. Usar la CA de inspección de confianza ocultaría el problema; la velocidad no tiene nada que ver.", ["Usar otra CA no hace que el handshake sea más rápido.", null, "La CA puede firmar cualquier certificado; el punto es que los clientes no confían en esta.", "Qué CA firma el certificado no afecta lo que puede ver el servidor."]],
  "x29": ["El HTTPS entrante hacia un servidor web interno debe inspeccionarse por completo con IPS. Los clientes externos no deben ver un certificado de CA del FortiGate. ¿Qué debe configurar el administrador?", ["Certificate inspection en la política entrante", "Deep inspection usando la CA predeterminada de Fortinet", "Un perfil de DNS filter en la política de la VIP del servidor", "Inspección protect-server con el propio certificado del servidor"], "La deep inspection entrante en modo de protección de servidor usa el propio certificado y la clave del servidor, así que los clientes ven el certificado real mientras el FortiGate descifra. Certificate inspection solo lee los datos del handshake y no puede inspeccionar el contenido.", ["Certificate inspection lee solo los datos del handshake, así que IPS no puede ver el contenido.", "Los clientes verían un certificado emitido por la CA del FortiGate, lo cual no está permitido.", "Un DNS filter revisa consultas; no inspecciona el contenido HTTPS entrante.", null]],
  "x30": ["Deep inspection está activada, pero el administrador quiere omitir el descifrado de sitios de confianza muy conocidos que a menudo fallan con la inspección, sin enumerarlos uno por uno. ¿Qué opción es la adecuada?", ["Exentar la lista de sitios web de buena reputación de FortiGuard", "Cambiar el perfil a certificate inspection", "Agregar cada sitio al filtro de URL estático como Allow", "Configurar el manejo de certificados no confiables en Ignore"], "El perfil de inspección SSL puede exentar la lista de sitios web de buena reputación de FortiGuard, que se mantiene por ti. Cambiar a certificate inspection dejaría de descifrar todo, no solo los sitios de confianza.", [null, "Certificate inspection dejaría de descifrar todo, no solo los sitios de confianza.", "Allow en el filtro de URL deja la sesión descifrada por el perfil SSL de todos modos.", "Esta configuración maneja certificados no válidos; no exenta sitios de confianza."]],
  "x31": ["El personal de RR. HH. debe poder navegar la categoría Job Search, pero los demás no. Todos los usuarios comparten una política sin requisito de usuario. ¿Qué acción de web filter funciona?", ["Warning, mostrado a todos los usuarios", "Monitor, con el registro habilitado", "Authenticate, permitiendo al grupo de RR. HH.", "Block, con una lista de URL exentas para RR. HH."], "La acción Authenticate pide credenciales y deja pasar solo a los miembros de los grupos seleccionados, como RR. HH. Warning permite que cualquiera continúe, así que no dejaría fuera al resto del personal.", ["Warning permite que cualquiera continúe, así que el personal que no es de RR. HH. igual podría llegar a los sitios.", "Monitor permite a todos y solo registra las visitas.", null, "Las entradas de URL estáticas aplican a todos en la política; no pueden distinguir a RR. HH. de los demás."]],
  "x32": ["Los profesores a veces necesitan acceso temporal a categorías bloqueadas para una clase, sin que el administrador edite el perfil de web filter cada vez. ¿Qué función es la adecuada?", ["Cambiar la acción de la categoría a Monitor", "Web filter overrides hacia otro perfil durante un tiempo definido", "Entradas del filtro de URL estático con la acción Exempt", "Quitar el web filter de la política durante el horario de clases"], "Los web filter overrides permiten que usuarios o grupos autorizados cambien a un perfil alternativo durante un tiempo limitado y luego vuelvan al original. Cambiar la categoría a Monitor la abriría a todos los usuarios de forma permanente.", ["Monitor abriría la categoría a todos los usuarios de forma permanente.", null, "Las entradas Exempt son permanentes para todos los del perfil, no temporales por usuario.", "Quitar el filtro expone a todos los usuarios a todas las categorías durante ese tiempo."]],
  "x33": ["example.com está configurado como Block en el filtro de URL estático, mientras que FortiGuard lo califica en una categoría que el perfil permite. ¿Qué ocurre cuando los usuarios navegan hacia él?", ["Se permite, ya que las categorías de FortiGuard prevalecen sobre las listas locales", "Se permite, pero solo para usuarios autenticados", "Depende de qué filtro se configuró más recientemente", "Se bloquea, porque el filtro de URL estático se revisa primero"], "El filtro de URL estático se evalúa antes que el filtrado por categorías de FortiGuard, así que su acción Block gana. Las categorías de FortiGuard no prevalecen sobre las entradas de URL locales; solo aplican cuando el filtro de URL no tiene coincidencia.", ["Las categorías no prevalecen sobre las entradas locales; el filtro de URL estático se revisa primero.", "La entrada Block aplica a todos; la autenticación no la cambia.", "El orden de evaluación es fijo y no depende de cuándo se agregaron las entradas.", null]],
  "x34": ["El DNS filter bloquea dominios maliciosos, pero algunos navegadores igual llegan a ellos. Esos navegadores usan DNS over HTTPS hacia resolvers públicos. ¿Cuál es la MEJOR solución?", ["Bloquear DoH, por ejemplo con application control, para que el DNS pase por el filtro", "Configurar la acción ante error de calificación del DNS filter en block", "Agregar los dominios a la lista de URL estática del web filter con la acción Monitor", "Activar la aplicación forzada de safe search en el DNS filter"], "Un DNS filter solo ve consultas DNS en texto plano; bloquear DNS over HTTPS obliga a los navegadores a volver al DNS que el FortiGate puede filtrar. La configuración ante error de calificación aplica solo cuando no se puede llegar a FortiGuard, que no es el problema aquí.", [null, "La acción ante error de calificación aplica solo cuando no se puede llegar a FortiGuard.", "Monitor solo registra y permite, y no detiene las consultas DNS over HTTPS.", "Safe search controla los resultados de búsqueda, no qué resolver usa el navegador."]],
  "x35": ["Una escuela quiere forzar safe search en Google, Bing y YouTube por HTTPS, pero no implementará deep inspection. ¿Qué función es la adecuada?", ["Safe search del web filter con certificate inspection", "Un sensor de application control que bloquee las búsquedas", "La opción enforce safe search del DNS filter", "Entradas del filtro de URL estático para las búsquedas no seguras"], "El DNS filter fuerza safe search respondiendo a esos dominios de búsqueda con las direcciones restringidas de los proveedores, lo que no requiere descifrado. El safe search del web filter reescribe las URL, así que para HTTPS necesita deep inspection.", ["Para HTTPS, el safe search del web filter reescribe las URL y necesita deep inspection.", "Bloquear los buscadores va mucho más allá de forzar safe search.", null, "El filtrado de URL de rutas HTTPS necesita descifrado, que la escuela rechaza."]],
  "x36": ["Una aplicación de chat salta entre puertos para evadir los firewalls. ¿Por qué application control es mejor para bloquearla que las políticas basadas en puertos?", ["Bloquea todos los puertos mayores a 1024 por defecto", "Identifica las aplicaciones por firmas, no por puerto", "Usa el filtro de URL estático para encontrar aplicaciones", "Solo funciona con inspección basada en proxy"], "Application control compara el tráfico con firmas de aplicaciones, así que reconoce la aplicación en cualquier puerto. Bloquear puertos no es su forma de funcionar, y application control es basado en flujo, no solo en proxy.", ["Application control no bloquea rangos de puertos; compara firmas.", null, "El filtro de URL estático es una función de web filter, no la forma en que se identifican las aplicaciones.", "Application control es basado en flujo; no necesita el modo proxy."]],
  "x37": ["El administrador debe bloquear todas las aplicaciones que FortiGuard califica con el nivel de riesgo más alto, sin importar la categoría y sin nombrar cada aplicación. ¿Qué se debe agregar al sensor?", ["Un application override para cada aplicación riesgosa", "Un bloqueo de la categoría de web filter correspondiente", "Un IPS sensor filtrado por severidad crítica", "Un filter override que coincida con la calificación de riesgo"], "Un filter override coincide con las aplicaciones por atributos como riesgo, comportamiento, proveedor o popularidad, así que también detecta nuevas aplicaciones de alto riesgo. Un application override nombra firmas específicas, lo que el administrador quería evitar.", ["Los overrides por aplicación requieren nombrar cada aplicación, lo que el administrador quiere evitar.", "Las categorías de web filter aplican a URL, no a las calificaciones de riesgo de las aplicaciones.", "La severidad de IPS califica ataques, no los niveles de riesgo de las aplicaciones.", null]],
  "x38": ["Los usuarios descargan instaladores con adware incluido que no se clasifican como virus, y el perfil de antivirus los deja pasar. ¿Qué configuración apunta a estos archivos?", ["La detección de grayware en la configuración del antivirus", "Content disarm en el antivirus basado en flujo", "Un límite mayor para archivos sobredimensionados", "IPS fail-open en la política"], "La detección de grayware atrapa software no deseado, como adware y riskware, que no es un virus. Content disarm and reconstruction elimina el contenido activo de los documentos y es una función del modo proxy, no un detector de adware.", [null, "CDR elimina el contenido activo de los documentos y es una función de proxy, no detección de adware.", "Un límite mayor solo significa que se analizan archivos más grandes; el adware sigue sin marcarse.", "IPS fail-open decide qué pasa cuando IPS está sobrecargado; no es un control de archivos."]],
  "x39": ["La política exige que los archivos demasiado grandes para analizarse se bloqueen en lugar de dejarlos pasar. ¿Dónde se configura esto?", ["La opción content disarm del perfil de antivirus", "La configuración basada en tasa del IPS sensor", "La acción para archivos sobredimensionados en protocol options", "La acción ante error de calificación del DNS filter"], "El perfil de protocol options define el umbral de tamaño y si los archivos sobredimensionados se bloquean o se dejan pasar. Content disarm and reconstruction maneja el contenido de los documentos y no decide qué pasa con los archivos sobredimensionados.", ["CDR elimina el contenido activo de los documentos; no define el manejo de archivos sobredimensionados.", "La configuración de IPS basada en tasa cuenta eventos repetidos, no tamaños de archivo.", null, "El DNS filter trabaja sobre consultas de nombres y nunca ve archivos."]],
  "x40": ["Un servidor SSH en la DMZ recibe intentos repetidos de adivinar contraseñas desde afuera. ¿Qué función de IPS está diseñada para detectar este patrón?", ["Una política DoS con una anomalía icmp_flood", "Firmas basadas en tasa (rate-based) en el IPS sensor", "Bloqueo de comando y control de botnets", "Un application override que permita SSH"], "Las firmas de IPS basadas en tasa se activan cuando un evento, como un inicio de sesión fallido, se repite por encima de un umbral dentro de una ventana de tiempo, lo que corresponde a la fuerza bruta. Una anomalía icmp_flood cuenta paquetes ICMP, así que nunca vería intentos de inicio de sesión SSH.", ["Una anomalía icmp_flood cuenta paquetes ICMP y nunca vería los inicios de sesión SSH.", null, "El bloqueo de botnets detiene conexiones C&C salientes, no la adivinación de contraseñas entrante.", "Un override que permite SSH no hace nada para detener los intentos repetidos de inicio de sesión."]],
  "x41": ["Tras un intento de exploit crítico, el SOC quiere que la dirección del atacante quede bloqueada para todo el tráfico que pasa por el FortiGate durante un tiempo, no solo en esa sesión. ¿Qué acción de IPS hace esto?", ["Monitor con registro de paquetes", "Reset de la sesión coincidente", "Pass con un correo de alerta", "Quarantine del atacante"], "La acción quarantine prohíbe la IP del atacante durante un tiempo configurado, bloqueando todo su tráfico. Reset solo termina la sesión que coincidió con la firma; el atacante podría simplemente intentarlo de nuevo.", ["Monitor solo registra el evento y deja que el ataque continúe.", "Reset termina solo la sesión coincidente; el atacante puede simplemente intentarlo de nuevo.", "Pass deja pasar el tráfico, lo contrario de lo que se busca.", null]],
  "x42": ["El administrador sospecha que las firmas de IPS y antivirus están desactualizadas. ¿Qué comando muestra las versiones instaladas de los motores y las bases de datos y cuándo se actualizaron por última vez?", ["diagnose autoupdate versions", "get system performance status", "diagnose debug rating", "diagnose sys top"], "diagnose autoupdate versions lista cada motor y base de datos de FortiGuard con su versión y la hora de la última actualización. diagnose debug rating es para los servidores de calificación del web filter, no para las versiones de firmas.", [null, "Esto muestra los totales de CPU, memoria y sesiones, no las versiones de las firmas.", "Esto muestra los servidores de calificación del web filter, no las bases de datos de IPS y AV.", "Esto lista los procesos por CPU y memoria, no las versiones de FortiGuard."]],
  "x43": ["Los registros de filtrado web muestran errores de calificación. ¿Qué comando muestra los servidores de calificación de FortiGuard que usa el FortiGate y su estado?", ["diagnose autoupdate status", "execute update-now", "diagnose debug rating", "get system fortiguard"], "diagnose debug rating lista los servidores de FortiGuard que se usan para las calificaciones del web filter, con su peso, tiempo de ida y vuelta y pérdida de paquetes. execute update-now fuerza una actualización de firmas, lo que no muestra el estado de los servidores de calificación.", ["Esto muestra la configuración y el horario de las actualizaciones, no el estado de los servidores de calificación.", "Esto fuerza una actualización de firmas y no informa sobre los servidores de calificación.", null, "Esto muestra la configuración de FortiGuard, no el estado en vivo de los servidores de calificación."]],
  "x44": ["Un FortiGate tiene 10.0.0.0/8 por port2 con distancia 5, y 10.20.0.0/16 por port3 con distancia 20. ¿Qué camino toma el tráfico hacia 10.20.5.9?", ["port2, porque su distancia es menor", "port3, porque el prefijo más largo gana primero", "Ambos, mediante equal-cost multipath", "port2, porque se configuró primero"], "La búsqueda de rutas elige el prefijo coincidente más largo antes de comparar la distancia, así que gana el /16 por port3. La distancia solo decide entre rutas hacia el mismo prefijo, y estas no lo son.", ["La distancia solo se compara entre rutas hacia el mismo prefijo.", null, "ECMP necesita rutas hacia el mismo prefijo; estos prefijos son distintos.", "El orden en que se configuraron las rutas no afecta la selección de rutas."]],
  "x45": ["Hay dos rutas predeterminadas iguales en la tabla, pero todas las sesiones de cada usuario salen por un solo enlace. El administrador quiere repartir las sesiones usando origen y destino juntos. ¿Qué debe cambiar?", ["La prioridad de una de las dos rutas", "Un link health monitor en ambas interfaces", "Una policy route para cada destino común", "El método ECMP a source-destination IP"], "El método ECMP predeterminado se basa en la IP de origen, así que un usuario se queda en un enlace; el método source-destination IP reparte las sesiones de un usuario también por destino. Cambiar la prioridad dejaría activa solo una ruta y eliminaría ECMP por completo.", ["Prioridades distintas dejarían solo una ruta en uso y eliminarían ECMP.", "Los link health monitors detectan enlaces caídos; no cambian cómo se reparten las sesiones.", "Las policy routes por destino son manuales y difíciles de mantener; no son un método de balanceo de carga.", null]],
  "x46": ["¿Qué comando muestra exactamente qué ruta usaría el FortiGate para llegar a 203.0.113.50?", ["get router info routing-table details 203.0.113.50", "get router info routing-table database", "diagnose sniffer packet any 'host 203.0.113.50'", "get system arp"], "get router info routing-table details con una IP muestra la mejor ruta coincidente para ese destino. La base de datos de enrutamiento lista todas las rutas, incluidas las inactivas, pero no elige la que se usa para una dirección dada.", [null, "La base de datos lista todas las rutas, incluidas las inactivas, sin elegir la que se usa.", "El sniffer muestra los paquetes en el cable, no la decisión de enrutamiento para ellos.", "La tabla ARP asigna IP a MAC en las subredes locales; no muestra rutas."]],
  "x47": ["Una policy route envía todo el tráfico de la LAN al ISP2. El tráfico hacia la red interna 10.0.0.0/8 debe seguir usando la tabla de enrutamiento normal. ¿Qué debe agregar el administrador?", ["Una ruta blackhole para 10.0.0.0/8 con distancia alta", "Un valor de prioridad más bajo en la ruta estática existente hacia 10.0.0.0/8 por la LAN", "Una policy route encima para 10.0.0.0/8 configurada para detener el policy routing", "Una segunda policy route debajo que apunte a la LAN"], "Una policy route con la acción stop policy routing, colocada encima de la otra, envía el tráfico coincidente a la tabla de enrutamiento. Una policy route colocada debajo nunca se alcanzaría, porque gana la primera policy route coincidente.", ["Una ruta blackhole descartaría el tráfico hacia 10.0.0.0/8 si alguna vez se convirtiera en la mejor ruta.", "Las policy routes se revisan antes que la tabla de enrutamiento, así que la prioridad de la ruta se ignora.", null, "Gana la primera policy route coincidente, así que una policy route debajo nunca se alcanzaría."]],
  "x48": ["El tráfico de la LAN llega a un servidor a través del FortiGate, pero las respuestas del servidor regresan por otro router, y el FortiGate descarta los paquetes posteriores de la sesión. ¿Cuál es la MEJOR solución?", ["Activar el enrutamiento asimétrico de forma global", "Corregir el enrutamiento para que ambas direcciones pasen por el FortiGate", "Deshabilitar la verificación RPF en la interfaz LAN", "Aumentar el session TTL de la política"], "La inspección con estado necesita ver ambas direcciones de una sesión, así que la solución correcta es un enrutamiento simétrico. Habilitar el enrutamiento asimétrico hace que el FortiGate deje de inspeccionar correctamente, lo que debilita la seguridad.", ["El modo de enrutamiento asimétrico debilita la inspección con estado y es un último recurso.", null, "RPF verifica el origen del primer paquete; no ayuda con sesiones que se ven solo a medias.", "Un TTL más largo mantiene abierta la sesión, pero el FortiGate sigue viendo solo una dirección."]],
  "x49": ["¿Qué comando muestra la latencia, el jitter, la pérdida de paquetes y el estado alive actuales de cada miembro de SD-WAN para un performance SLA?", ["diagnose sys sdwan service", "get router info routing-table all", "diagnose vpn tunnel list", "diagnose sys sdwan health-check"], "diagnose sys sdwan health-check informa los resultados de los sondeos y el estado alive o dead por miembro para cada performance SLA. diagnose sys sdwan service muestra las reglas de SD-WAN y los miembros que eligen, no las mediciones de los sondeos.", ["Esto muestra las reglas de SD-WAN y los miembros elegidos, no los resultados de los sondeos.", "La tabla de enrutamiento muestra rutas, no latencia ni pérdida de paquetes.", "Esto lista las SA de fase 2 de IPsec, no las mediciones de SLA de SD-WAN.", null]],
  "x50": ["¿Cómo maneja SD-WAN el tráfico que no coincide con ninguna de las reglas de SD-WAN configuradas?", ["La regla implícita lo envía según la tabla de enrutamiento y el balanceo de carga", "Lo descarta la regla implícita de denegar de SD-WAN", "Siempre usa el primer miembro de la zona", "Usa el miembro que en ese momento tenga la latencia medida más baja en su SLA"], "El tráfico sin coincidencia cae en la regla implícita, que usa la tabla de enrutamiento y el método de balanceo de carga de SD-WAN. No existe un deny implícito en las reglas de SD-WAN; el descarte queda a cargo de las políticas de firewall.", [null, "No existe una regla implícita de denegar en SD-WAN; las políticas de firewall deciden qué se descarta.", "El tráfico sin coincidencia se balancea; no siempre se envía al primer miembro.", "Elegir por la latencia más baja es una estrategia de regla, no el comportamiento predeterminado para el tráfico sin coincidencia."]],
  "x51": ["El ISP bloquea ICMP hacia el servidor de sondeo del SLA, así que SD-WAN marca al miembro como dead aunque la navegación funciona. ¿Qué debe cambiar el administrador?", ["Bajar el umbral de latencia del SLA", "Quitar al miembro de la zona", "Usar un sondeo HTTP o DNS en su lugar", "Agregar una ruta blackhole hacia el sondeo"], "Los performance SLA pueden sondear con otros protocolos, como HTTP o DNS, que pasan donde ICMP está filtrado. Bajar el umbral de latencia no sirve cuando no llega ninguna respuesta de sondeo.", ["Un umbral distinto no sirve de nada cuando no vuelve ninguna respuesta de sondeo.", "Quitar al miembro desecha un enlace que funciona en lugar de corregir el sondeo.", null, "Una ruta blackhole haría que el servidor de sondeo fuera totalmente inalcanzable."]],
  "x52": ["Un administrador necesita confirmar hacia qué miembro está dirigiendo el tráfico en este momento una regla SD-WAN específica. ¿Qué comando debe usar?", ["diagnose sys sdwan health-check", "diagnose sys sdwan service", "get router info routing-table database", "diagnose debug application ike -1"], "diagnose sys sdwan service lista cada regla de SD-WAN con sus miembros en su orden actual de preferencia. El comando health-check muestra los resultados de los sondeos del SLA, que alimentan la regla, pero no muestra la elección de la regla.", ["Esto muestra los resultados de los sondeos del SLA que alimentan la regla, no la elección de la regla.", null, "La base de datos de enrutamiento lista rutas, no las decisiones de las reglas de SD-WAN.", "Esto muestra la negociación IKE de las VPN y no tiene relación con las reglas de SD-WAN."]],
  "x53": ["Ambos pares de un túnel sitio a sitio IKEv1 tienen IP estáticas. ¿Por qué normalmente se prefiere main mode en lugar de aggressive mode?", ["Main mode protege las identidades de los pares", "Main mode usa menos mensajes para completarse", "Aggressive mode no puede usar claves precompartidas", "Main mode no necesita el puerto UDP 500"], "Main mode cifra el intercambio de identidades, mientras que aggressive mode envía las identidades en texto claro para ahorrar mensajes. Es aggressive mode, no main mode, el que usa menos mensajes.", [null, "Main mode usa más mensajes, no menos; esa es la ventaja y el costo de aggressive mode.", "Aggressive mode funciona con claves precompartidas; es uno de sus usos comunes.", "Ambos modos de IKEv1 usan UDP 500 para IKE."]],
  "x54": ["¿Cuál es una característica de IKEv2 en comparación con IKEv1?", ["La elección entre main mode y aggressive mode", "Solo funciona con VPN basadas en políticas", "No tiene soporte para NAT traversal", "EAP integrado para la autenticación de usuarios"], "IKEv2 incluye EAP para la autenticación de usuarios como parte del protocolo. Main mode y aggressive mode pertenecen a IKEv1; IKEv2 tiene un solo flujo de intercambio.", ["Main mode y aggressive mode pertenecen a IKEv1, no a IKEv2.", "IKEv2 funciona tanto con túneles basados en rutas como en políticas.", "IKEv2 incluye soporte para NAT traversal.", null]],
  "x55": ["El debug de IKE muestra 'no SA proposal chosen' mientras se negocia la fase 1. ¿Cuál es la causa MÁS probable?", ["La clave precompartida es distinta entre los pares", "Falta la ruta hacia la LAN remota", "Difiere la configuración de cifrado, hash o grupo DH", "El túnel aún no tiene política de firewall"], "No proposal chosen significa que los pares no encontraron un conjunto común de configuración de cifrado, autenticación y grupo DH. Una clave precompartida incorrecta aparece más adelante en el intercambio, después de haber acordado una propuesta.", ["Una clave precompartida incorrecta falla más adelante, después de haber acordado una propuesta.", "Las rutas afectan el tráfico una vez que el túnel está activo, no el intercambio de propuestas.", null, "Las políticas de firewall no detienen la negociación de propuestas IKE en sí."]],
  "x56": ["diagnose vpn tunnel list muestra que el contador de paquetes cifrados sube, mientras que el contador de descifrados se queda en cero. ¿Qué sugiere esto?", ["La fase 1 del FortiGate local está caída", "El tráfico entra al túnel, pero no vuelve nada", "La política de firewall local está bloqueando que el tráfico entre al túnel", "Dead peer detection está deshabilitado en el túnel"], "Que suba el contador de cifrado significa que el lado local está enviando; cero descifrados significa que no hay tráfico de retorno, así que revisa las rutas, políticas o selectores del lado remoto. Si la política local estuviera bloqueando, el contador de cifrado no subiría.", ["Si la fase 1 estuviera caída, no se cifraría ningún tráfico.", null, "Una política local que bloquea impediría que subiera el contador de cifrado.", "DPD solo verifica que el par esté vivo; desactivarlo no detiene el tráfico de retorno."]],
  "x57": ["La oficina central tiene dos entradas de fase 1 dial-up IKEv1 con claves precompartidas distintas para dos grupos de sucursales. Las sucursales siguen coincidiendo con la entrada equivocada. ¿Qué permite a la oficina central elegir la correcta?", ["Main mode con el mismo peer ID en todas las sucursales", "Deshabilitar dead peer detection en ambas entradas", "Selectores de fase 2 separados en cada sucursal", "Aggressive mode con un peer ID único por grupo"], "En IKEv1 con claves precompartidas, aggressive mode envía el peer ID al inicio, así que la oficina central puede asociarlo con la entrada dial-up correcta. Los selectores de fase 2 se negocian después de la fase 1, así que no pueden ayudar a elegir la entrada de fase 1.", ["Main mode envía las identidades demasiado tarde para elegir entre entradas dial-up con claves distintas.", "DPD verifica que el par esté vivo y no participa en asociar un par con una entrada de fase 1.", "Los selectores de fase 2 se negocian después de la fase 1, así que no pueden elegir la entrada.", null]],
  "x58": ["Una organización con una versión posterior de FortiOS 7.6, en la que el modo túnel de SSL VPN ya no está disponible, necesita acceso remoto de túnel completo para laptops. ¿Qué debe usar?", ["VPN IPsec dial-up con FortiClient", "Modo túnel de SSL VPN en un puerto nuevo", "Un túnel sitio a sitio para cada laptop", "Agentless VPN para todas las aplicaciones"], "Sin el modo túnel, el acceso remoto de túnel completo se hace con IPsec dial-up de FortiClient. Agentless VPN (el nuevo nombre del modo web) da acceso por navegador a recursos seleccionados, no un túnel de red completo.", [null, "El escenario indica que el modo túnel ya no está disponible en estas versiones.", "Los túneles sitio a sitio por laptop no se adaptan a clientes móviles ni escalan bien.", "Agentless VPN da acceso por navegador a recursos seleccionados, no un túnel completo."]],
  "x59": ["Los sitios A, B y C tienen cada uno un túnel hacia los otros dos, mientras que el sitio D tiene un túnel solo hacia el sitio A. ¿Cómo se llama esta topología?", ["Malla completa", "Hub and spoke con D como hub", "Malla parcial", "Solo punto a punto"], "Una malla parcial tiene algunos sitios conectados con todos los demás y otros con menos enlaces. Una malla completa requeriría que D también tuviera túneles hacia B y C.", ["Una malla completa requeriría que D también tuviera túneles hacia B y C.", "D tiene un solo túnel, así que no puede ser el hub.", null, "Varios sitios tienen más de un túnel, así que no son solo enlaces punto a punto."]],
  "x60": ["La fase 2 de un túnel se levanta solo después de que los usuarios envían tráfico, lo que retrasa la primera conexión de un sistema de monitoreo. ¿Qué configuración de fase 2 la levanta sin esperar tráfico?", ["DPD configurado en on idle", "Auto-negotiate", "Perfect forward secrecy", "Aggressive mode"], "Auto-negotiate levanta la fase 2 en cuanto la fase 1 está lista y la mantiene activa. Dead peer detection verifica si el par está vivo; no negocia las SA de fase 2 antes del tráfico.", ["DPD verifica si el par está vivo; no levanta la fase 2 antes del tráfico.", null, "PFS agrega un nuevo intercambio DH para las claves de la fase 2; no inicia la SA antes.", "Aggressive mode es una opción de la fase 1 y no inicia la fase 2."]]
});
